INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.BL_SP_SC_SK_CK', 'ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO', 'english', 2, 'Hear and tell apart words with bl, sp, sc, sk and ck', ARRAY['ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.a', 'ENGL.G2.READIN.T1_FLUENCY.a']::text[], 'The child hears and picks out words with bl, sp, sc, sk and ck (sc and sk both say /sk/) in a sentence or conversation (for example black, spoon, school, desk, duck) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS', 'ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO', 'english', 2, 'Know and choose the new words of the theme', ARRAY['ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.b', 'ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.c', 'ENGL.G2.LISTEN.T5_PRONUNCIATION_AND_VO.c', 'ENGL.G2.LISTEN.T6_PRONUNCIATION_AND_VO.c', 'ENGL.G2.LISTEN.T7_PRONUNCIATION_AND_VO.c', 'ENGL.G2.LISTEN.T9_PRONUNCIATION_AND_VO.c', 'ENGL.G2.LISTEN.T10_PRONUNCIATION_AND_VO.c', 'ENGL.G2.LISTEN.T12_PRONUNCIATION_AND_VO.c', 'ENGL.G2.LISTEN.T13_BY_THE_END_OF_THE_SU.c', 'ENGL.G2.LISTEN.T15_PRONUNCIATION_AND_VO.c', 'ENGL.G2.READIN.T4_COMPREHENSION.a', 'ENGL.G2.WRITIN.T11_GUIDED_WRITING.a', 'ENGL.G2.WRITIN.T14_GUIDED_WRITING.a']::text[], 'The child chooses the theme word that fits a sentence or picture (for example duster, sweep, matatu, July, shopkeeper, seedling, bandage, chalkboard, calf, left, litter, radio, dance, chores, sick) and does not swap it for a word of the same group. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the word that fits","match the word to the picture","fill the gap"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.FOLLOW_TWO_STEP', 'ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO', 'english', 2, 'Listen to and carry out a two-step spoken instruction', ARRAY['ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.c', 'ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.d', 'ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.d', 'ENGL.G2.LISTEN.T6_PRONUNCIATION_AND_VO.d', 'ENGL.G2.LISTEN.T7_PRONUNCIATION_AND_VO.d', 'ENGL.G2.LISTEN.T8_PRONUNCIATION_AND_VO.c', 'ENGL.G2.LISTEN.T9_PRONUNCIATION_AND_VO.d', 'ENGL.G2.LISTEN.T14_PRONUNCIATION_AND_VO.d', 'ENGL.G2.LISTEN.T15_PRONUNCIATION_AND_VO.d']::text[], 'The child listens to a two-step instruction said once (Pick up the duster and give it to Wanjiru) and does both steps in the order given. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["do what the teacher says","Simon says with two steps","draw what you hear"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.READIN.T1_FLUENCY.READ_ACCURATELY', 'ENGL.G2.READIN.T1_FLUENCY', 'english', 2, 'Read a Grade 2 text aloud accurately and at the right speed', ARRAY['ENGL.G2.READIN.T1_FLUENCY.b', 'ENGL.G2.READIN.T3_FLUENCY.b', 'ENGL.G2.READIN.T4_FLUENCY.b', 'ENGL.G2.READIN.T6_FLUENCY.b', 'ENGL.G2.READIN.T6_FLUENCY.c', 'ENGL.G2.READIN.T8_FLUENCY.c', 'ENGL.G2.READIN.T9_FLUENCY.b', 'ENGL.G2.READIN.T11_FLUENCY.c', 'ENGL.G2.READIN.T13_FLUENCY.c', 'ENGL.G2.READIN.T14_FLUENCY.b', 'ENGL.G2.READIN.T14_FLUENCY.c']::text[], 'The child reads a short Grade 2 text aloud with almost every word right, sounding out new words with the letter-sounds learnt instead of guessing, at a steady speed (about 40 to 60 words a minute is a guide, to confirm by the teacher). Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["read aloud to the teacher","read a page of a graded reader","read a short passage"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.READIN.T1_COMPREHENSION.PREDICT', 'ENGL.G2.READIN.T1_COMPREHENSION', 'english', 2, 'Predict what will happen in a story from the title, pictures and clues', ARRAY['ENGL.G2.READIN.T1_COMPREHENSION.a', 'ENGL.G2.READIN.T3_COMPREHENSION.a', 'ENGL.G2.LANGUA.T5_COMPREHENSION.a', 'ENGL.G2.READIN.T6_COMPREHENSION.a', 'ENGL.G2.READIN.T7_COMPREHENSION.b', 'ENGL.G2.READIN.T8_COMPREHENSION.a', 'ENGL.G2.READIN.T10_COMPREHENSION.a', 'ENGL.G2.READIN.T11_COMPREHENSION.a', 'ENGL.G2.READIN.T12_COMPREHENSION.b', 'ENGL.G2.READIN.T13_COMPREHENSION.a', 'ENGL.G2.READIN.T14_COMPREHENSION.a', 'ENGL.G2.READIN.T15_COMPREHENSION.a']::text[], 'The child uses the title, the pictures and what has happened so far to say what will happen next and names the clue. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what will happen next","which clue helps","choose the best prediction"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.READIN.T1_COMPREHENSION.WORD_FROM_CONTEXT', 'ENGL.G2.READIN.T1_COMPREHENSION', 'english', 2, 'Work out the meaning of a new word from the sentence and picture', ARRAY['ENGL.G2.READIN.T1_COMPREHENSION.b', 'ENGL.G2.READIN.T2_COMPREHENSION.a', 'ENGL.G2.READIN.T3_COMPREHENSION.b', 'ENGL.G2.READIN.T4_COMPREHENSION.b', 'ENGL.G2.LANGUA.T5_COMPREHENSION.b', 'ENGL.G2.READIN.T6_COMPREHENSION.b', 'ENGL.G2.READIN.T8_COMPREHENSION.b', 'ENGL.G2.READIN.T10_COMPREHENSION.b', 'ENGL.G2.READIN.T11_COMPREHENSION.c', 'ENGL.G2.READIN.T12_COMPREHENSION.d', 'ENGL.G2.READIN.T13_COMPREHENSION.c', 'ENGL.G2.READIN.T14_COMPREHENSION.c', 'ENGL.G2.READIN.T15_COMPREHENSION.c']::text[], 'The child uses the words around a new word and the picture to choose its meaning in this sentence. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what does the word mean","which word could replace it","which clue helps"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.READIN.T1_COMPREHENSION.DIRECT_QUESTIONS', 'ENGL.G2.READIN.T1_COMPREHENSION', 'english', 2, 'Answer questions whose answers are stated in the text', ARRAY['ENGL.G2.READIN.T1_COMPREHENSION.c', 'ENGL.G2.READIN.T2_COMPREHENSION.b', 'ENGL.G2.READIN.T3_COMPREHENSION.c', 'ENGL.G2.READIN.T4_COMPREHENSION.c', 'ENGL.G2.LANGUA.T5_COMPREHENSION.c', 'ENGL.G2.READIN.T6_COMPREHENSION.c', 'ENGL.G2.READIN.T7_COMPREHENSION.c', 'ENGL.G2.READIN.T8_COMPREHENSION.c', 'ENGL.G2.READIN.T10_COMPREHENSION.c', 'ENGL.G2.READIN.T11_COMPREHENSION.d', 'ENGL.G2.READIN.T12_COMPREHENSION.c', 'ENGL.G2.READIN.T13_COMPREHENSION.d', 'ENGL.G2.READIN.T14_COMPREHENSION.d', 'ENGL.G2.READIN.T15_COMPREHENSION.d']::text[], 'The child finds the sentence that answers who, what, where or when and answers from the text, with the kind of answer the question word asks for. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["answer the question on the text","choose the best answer","which sentence tells you"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.WAS_WERE', 'ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS', 'english', 2, 'Use was and were for the past', ARRAY['ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.a', 'ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.b']::text[], 'The child picks was and were from a text and uses was with I, he, she and it, and were with we, you and they and plural nouns: We were at school. The children were happy. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.OBJECT_PRONOUNS', 'ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS', 'english', 2, 'Use us, you and them after a verb or a preposition', ARRAY['ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.a', 'ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.b', 'ENGL.G2.LANGUA.T3_VERBS_TO_HAVE_OBJECT.a', 'ENGL.G2.LANGUA.T3_VERBS_TO_HAVE_OBJECT.b']::text[], 'The child picks us, you and them from a text and uses them after a verb or a word like to and with (The teacher called us. Give them the books.), not as the subject. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.WRITIN.T1_HANDWRITING.DESCENDERS', 'ENGL.G2.WRITIN.T1_HANDWRITING', 'english', 2, 'Know the letters whose tails hang below the line', ARRAY['ENGL.G2.WRITIN.T1_HANDWRITING.a', 'ENGL.G2.WRITIN.T3_HANDWRITING.a']::text[], 'The child picks out g, j, p, q and y as letters whose tails hang below the line, in long words in a text, and spots a word where a tail sits on the line. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which letter has a tail","which word is written right","circle the tails"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.WRITIN.T1_HANDWRITING.HANDWRITING_NEAT', 'ENGL.G2.WRITIN.T1_HANDWRITING', 'english', 2, 'Form letters, ascenders and descenders neatly in long words', ARRAY['ENGL.G2.WRITIN.T1_HANDWRITING.b', 'ENGL.G2.WRITIN.T2_HANDWRITING.b', 'ENGL.G2.WRITIN.T3_HANDWRITING.b', 'ENGL.G2.WRITIN.T4_HANDWRITING.b', 'ENGL.G2.WRITIN.T7_SPELLING.b', 'ENGL.G2.WRITIN.T8_SPELLING.b']::text[], 'The child writes long words with every letter the right shape, tall letters reaching up, tails hanging down, small letters even, and a finger space between words. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["copy the long words","write the theme words neatly","write on the lines"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.CH_OA_SH_CL', 'ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO', 'english', 2, 'Hear and pick out words with ch, the long o sound, sh and cl', ARRAY['ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.a', 'ENGL.G2.READIN.T2_FLUENCY.a']::text[], 'The child hears and picks out words with /tʃ/ (ch), /əʊ/ (long o, as in home, boat), /ʃ/ (sh) and cl in a sentence or conversation (for example chair, soap, dish, clean) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.SAY_CONSONANT_SOUNDS', 'ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO', 'english', 2, 'Say words with consonant blends and the th, sh and ch sounds clearly', ARRAY['ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.b', 'ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.b', 'ENGL.G2.LISTEN.T6_PRONUNCIATION_AND_VO.b', 'ENGL.G2.LISTEN.T12_PRONUNCIATION_AND_VO.b', 'ENGL.G2.LISTEN.T13_BY_THE_END_OF_THE_SU.b', 'ENGL.G2.LISTEN.T14_PRONUNCIATION_AND_VO.b', 'ENGL.G2.LISTEN.T15_PRONUNCIATION_AND_VO.b', 'ENGL.G2.LISTEN.T5_PRONUNCIATION_AND_VO.b', 'ENGL.G2.READIN.T5_FLUENCY.b', 'ENGL.G2.READIN.T13_FLUENCY.b', 'ENGL.G2.READIN.T15_FLUENCY.b']::text[], 'The child says words with consonant blends (cl, fl, st, gl, br, cr, dr, fr, gr, pr, tr, sm, sn, sp, scr, spr, str, sw) as one beat with no vowel slipped in, keeps l and r apart, and says sh, ch, th (thin) and th (this) clearly. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say the word after the teacher","read the word list aloud","say the sentence"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.READIN.T2_FLUENCY.READ_WITH_FEELING', 'ENGL.G2.READIN.T2_FLUENCY', 'english', 2, 'Read aloud showing the right feelings and observing punctuation', ARRAY['ENGL.G2.READIN.T2_FLUENCY.c', 'ENGL.G2.READIN.T5_FLUENCY.c', 'ENGL.G2.READIN.T7_FLUENCY.b', 'ENGL.G2.READIN.T10_FLUENCY.b', 'ENGL.G2.READIN.T12_FLUENCY.c', 'ENGL.G2.READIN.T15_FLUENCY.c']::text[], 'The child stops at full stops, lifts the voice at a question mark, sounds excited at an exclamation mark and lets the voice and face show what a character feels. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["read a dialogue in parts","read it happily, read it sadly","read with the marks"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.READIN.T2_COMPREHENSION.INDIRECT_QUESTIONS', 'ENGL.G2.READIN.T2_COMPREHENSION', 'english', 2, 'Answer questions whose answers are shown by clues', ARRAY['ENGL.G2.READIN.T2_COMPREHENSION.b', 'ENGL.G2.READIN.T1_COMPREHENSION.c', 'ENGL.G2.READIN.T3_COMPREHENSION.c', 'ENGL.G2.READIN.T4_COMPREHENSION.c', 'ENGL.G2.LANGUA.T5_COMPREHENSION.c', 'ENGL.G2.READIN.T6_COMPREHENSION.c', 'ENGL.G2.READIN.T7_COMPREHENSION.c', 'ENGL.G2.READIN.T8_COMPREHENSION.c', 'ENGL.G2.READIN.T10_COMPREHENSION.c', 'ENGL.G2.READIN.T11_COMPREHENSION.d', 'ENGL.G2.READIN.T12_COMPREHENSION.c', 'ENGL.G2.READIN.T13_COMPREHENSION.d', 'ENGL.G2.READIN.T14_COMPREHENSION.d', 'ENGL.G2.READIN.T15_COMPREHENSION.d']::text[], 'The child answers simple how and why questions by joining two clues (Tom smiled and clapped: he was happy) and points to the clue. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["how did the character feel","why do you think","what clue tells you"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.READIN.T2_COMPREHENSION.TEXT_TO_LIFE', 'ENGL.G2.READIN.T2_COMPREHENSION', 'english', 2, 'Connect a text to his or her own life', ARRAY['ENGL.G2.READIN.T2_COMPREHENSION.c', 'ENGL.G2.READIN.T11_COMPREHENSION.b']::text[], 'The child names something in the text that is like his or her own life (I also sweep the house) and something different, keeping to what the text says. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["have you done this too","what would you do","which part is like your home"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.SUBJECT_PRONOUNS', 'ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A', 'english', 2, 'Use we, you and they as the subject', ARRAY['ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.a']::text[], 'The child picks we, you and they in a text and uses them as the subject (We sweep the house), not us or them, and does not repeat the subject (not My mother she cooks). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.VERB_DO', 'ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A', 'english', 2, 'Use do, does and did', ARRAY['ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.a', 'ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.b']::text[], 'The child uses does with he, she and it, do with I, you, we and they, and did for the past, with a plain verb after it: Did you sweep? She does the dishes. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.WRITIN.T2_HANDWRITING.ASCENDERS', 'ENGL.G2.WRITIN.T2_HANDWRITING', 'english', 2, 'Know the tall letters that reach up', ARRAY['ENGL.G2.WRITIN.T2_HANDWRITING.a', 'ENGL.G2.WRITIN.T3_HANDWRITING.a']::text[], 'The child picks out b, d, f, h, k, l and t as letters that reach up, in long words in a text, and spots a word where a tall letter is written short. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which letter is tall","which word is written right","circle the tall letters"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.S_L_FL_AY', 'ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO', 'english', 2, 'Hear and pick out words with s, l, fl and the long a sound', ARRAY['ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.a', 'ENGL.G2.READIN.T3_FLUENCY.a']::text[], 'The child hears and picks out words with /s/, /l/, fl and /eɪ/ (long a, as in train, play) in a sentence or conversation (for example bus, lorry, fly, train) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.USE_WORDS_SENTENCES', 'ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO', 'english', 2, 'Use new words in short spoken sentences', ARRAY['ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.c', 'ENGL.G2.LISTEN.T14_PRONUNCIATION_AND_VO.c']::text[], 'The child uses a new theme word in a short spoken sentence of four or more words, with the right meaning (I travelled by matatu), not a single word. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say a sentence with the word","tell your partner","answer in a sentence"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LANGUA.T3_VERBS_TO_HAVE_OBJECT.VERB_HAVE', 'ENGL.G2.LANGUA.T3_VERBS_TO_HAVE_OBJECT', 'english', 2, 'Use have, has and had', ARRAY['ENGL.G2.LANGUA.T3_VERBS_TO_HAVE_OBJECT.a', 'ENGL.G2.LANGUA.T3_VERBS_TO_HAVE_OBJECT.b']::text[], 'The child uses has with he, she and it, have with I, you, we and they, and had for the past: Baraka has a bicycle. We had a matatu ride. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.NG_EE_ST_GL', 'ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO', 'english', 2, 'Hear and pick out words with ng, the long e sound, st and gl', ARRAY['ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.a', 'ENGL.G2.READIN.T4_FLUENCY.a']::text[], 'The child hears and picks out words with /ŋ/ (ng), /iː/ (long e, as in sheep), st and gl in a sentence or conversation (for example sing, week, star, glad) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.SAY_VOWEL_SOUNDS', 'ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO', 'english', 2, 'Say short and long vowel sounds so the right word is heard', ARRAY['ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.b', 'ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.c', 'ENGL.G2.LISTEN.T7_PRONUNCIATION_AND_VO.b', 'ENGL.G2.LISTEN.T8_PRONUNCIATION_AND_VO.b', 'ENGL.G2.LISTEN.T9_PRONUNCIATION_AND_VO.b', 'ENGL.G2.LISTEN.T10_PRONUNCIATION_AND_VO.b', 'ENGL.G2.LISTEN.T11_PRONUNCIATION_AND_VO.b', 'ENGL.G2.LISTEN.T11_PRONUNCIATION_AND_VO.c', 'ENGL.G2.READIN.T2_FLUENCY.b', 'ENGL.G2.READIN.T8_FLUENCY.b', 'ENGL.G2.READIN.T12_FLUENCY.b']::text[], 'The child says English vowel sounds so a listener hears the right word: ship and sheep, cup and cap, pull and pool, cot and coat, bird (not bad), with weak vowels short (the a in banana). Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say the word after the teacher","say the pair: ship, sheep","read the word list aloud"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LANGUA.T4_SIMPLE_PAST_TENSE.SIMPLE_PAST', 'ENGL.G2.LANGUA.T4_SIMPLE_PAST_TENSE', 'english', 2, 'Use the simple past to talk about past activities', ARRAY['ENGL.G2.LANGUA.T4_SIMPLE_PAST_TENSE.a', 'ENGL.G2.LANGUA.T4_SIMPLE_PAST_TENSE.b']::text[], 'The child finds past verbs in a text and uses -ed for regular verbs (played, stopped) and the right form for common irregular ones (went, ate, saw), with time words such as yesterday and last month. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.WRITIN.T4_HANDWRITING.HANDWRITING_ASPECTS', 'ENGL.G2.WRITIN.T4_HANDWRITING', 'english', 2, 'Know what makes handwriting good: shape, spacing, lines and capitals', ARRAY['ENGL.G2.WRITIN.T4_HANDWRITING.a', 'ENGL.G2.WRITIN.T5_SPELLING.a']::text[], 'The child chooses the writing with well-formed letters, finger spaces, letters sitting on the line and capitals only where needed, and says what is wrong with poor writing. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which writing is best","what is wrong with this writing","spot the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.WRITIN.T4_HANDWRITING.GL_Y_WORDS', 'ENGL.G2.WRITIN.T4_HANDWRITING', 'english', 2, 'Make theme words with gl and y', ARRAY['ENGL.G2.WRITIN.T4_HANDWRITING.c']::text[], 'The child builds theme words with gl and y (glad, glue, July, sunny, January) from letters and spells them correctly. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["make a word with gl","fill in the missing letters","which word is spelt right"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T5_PRONUNCIATION_AND_VO.NT_SL_AR_ND_NK', 'ENGL.G2.LISTEN.T5_PRONUNCIATION_AND_VO', 'english', 2, 'Hear and pick out words with nt, sl, ar, nd and nk', ARRAY['ENGL.G2.LISTEN.T5_PRONUNCIATION_AND_VO.a', 'ENGL.G2.READIN.T5_FLUENCY.a']::text[], 'The child hears and picks out words with nt, sl, -ar (said /ɑː/), nd and nk in a sentence or conversation (for example plant, slow, market, sand, bank) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.WRITIN.T5_NOUNS_PLURALS_OF_IRR.IRREGULAR_PLURALS', 'ENGL.G2.WRITIN.T5_NOUNS_PLURALS_OF_IRR', 'english', 2, 'Use the plurals of irregular nouns', ARRAY['ENGL.G2.WRITIN.T5_NOUNS_PLURALS_OF_IRR.a', 'ENGL.G2.WRITIN.T5_NOUNS_PLURALS_OF_IRR.b']::text[], 'The child finds irregular plurals in a text and uses child and children, man and men, woman and women, foot and feet, tooth and teeth, and sheep and sheep in sentences about shopping. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.WRITIN.T5_SPELLING.SPELL_GRADE_WORDS', 'ENGL.G2.WRITIN.T5_SPELLING', 'english', 2, 'Spell Grade 2 words correctly', ARRAY['ENGL.G2.WRITIN.T5_SPELLING.b', 'ENGL.G2.WRITIN.T6_SPELLING.b', 'ENGL.G2.WRITIN.T8_SPELLING.b']::text[], 'The child spells common Grade 2 words of three to seven letters (money, shop, buy, garden, water, farmer) correctly and clearly. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct spelling","fill in the missing letters","spot the wrong spelling"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T6_PRONUNCIATION_AND_VO.EAR_TH_WH_TW', 'ENGL.G2.LISTEN.T6_PRONUNCIATION_AND_VO', 'english', 2, 'Hear and pick out words with ear, the two th sounds, wh and tw', ARRAY['ENGL.G2.LISTEN.T6_PRONUNCIATION_AND_VO.a', 'ENGL.G2.READIN.T6_FLUENCY.a']::text[], 'The child hears and picks out words with /ɪə/ (as in ear, deer), /θ/ (thin), /ð/ (this), wh (said /w/) and tw in a sentence or conversation (for example ear, thorn, there, wheel, twig) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LANGUA.T6_TENSE_PAST_CONTINUOU.PAST_CONTINUOUS', 'ENGL.G2.LANGUA.T6_TENSE_PAST_CONTINUOU', 'english', 2, 'Use the past continuous tense', ARRAY['ENGL.G2.LANGUA.T6_TENSE_PAST_CONTINUOU.a', 'ENGL.G2.LANGUA.T6_TENSE_PAST_CONTINUOU.b']::text[], 'The child picks past continuous sentences from a text and changes the present continuous into the past: I am watering the plants becomes I was watering the plants; they are digging becomes they were digging. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.WRITIN.T6_SPELLING.SPELL_TH_WH_TW_EAR', 'ENGL.G2.WRITIN.T6_SPELLING', 'english', 2, 'Spell words with th, wh, tw and ear', ARRAY['ENGL.G2.WRITIN.T6_SPELLING.a']::text[], 'The child spells garden words with th, wh, tw and ear (thorn, there, wheel, twig, near) with th, not t or d, and wh, not w or h alone. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct spelling","fill in the missing letters","spot the wrong spelling"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T7_PRONUNCIATION_AND_VO.ND_NK_AY_OA_IE', 'ENGL.G2.LISTEN.T7_PRONUNCIATION_AND_VO', 'english', 2, 'Hear and pick out words with nd, nk and the long a, o and i sounds', ARRAY['ENGL.G2.LISTEN.T7_PRONUNCIATION_AND_VO.a', 'ENGL.G2.READIN.T7_FLUENCY.a']::text[], 'The child hears and picks out words with nd, nk, /eɪ/ (cake), /əʊ/ (home) and /aɪ/ (bike) in a sentence or conversation (for example bandage, drink, pain, nose, knife) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.READIN.T7_COMPREHENSION.CHARACTERS_EVENTS', 'ENGL.G2.READIN.T7_COMPREHENSION', 'english', 2, 'Name and describe the characters and events in a text', ARRAY['ENGL.G2.READIN.T7_COMPREHENSION.a', 'ENGL.G2.READIN.T12_COMPREHENSION.a', 'ENGL.G2.READIN.T13_COMPREHENSION.b', 'ENGL.G2.READIN.T15_COMPREHENSION.b']::text[], 'The child names the people and animals in a story, says one thing about each (kind, brave, careless) and tells the main events. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["who is in the story","what happened","describe the character"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LANGUA.T7_CONJUNCTIONS.CONJ_OR', 'ENGL.G2.LANGUA.T7_CONJUNCTIONS', 'english', 2, 'Use or to give a choice', ARRAY['ENGL.G2.LANGUA.T7_CONJUNCTIONS.a', 'ENGL.G2.LANGUA.T7_CONJUNCTIONS.b']::text[], 'The child picks or in a sentence and uses it to give a choice (Do you want tea or milk?), and answers an or question by choosing one, not with yes. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose and or or","join with or","answer the question"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.WRITIN.T7_SPELLING.SPELL_NK_ND_AR', 'ENGL.G2.WRITIN.T7_SPELLING', 'english', 2, 'Spell words with nk, nd and ar', ARRAY['ENGL.G2.WRITIN.T7_SPELLING.a']::text[], 'The child spells three- to six-letter words with nk, nd and ar (pink, hand, car, park) with both final letters and ar, not a. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct spelling","fill in the missing letters","spot the wrong spelling"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T8_PRONUNCIATION_AND_VO.BR_SCHWA_EE_AY_OA', 'ENGL.G2.LISTEN.T8_PRONUNCIATION_AND_VO', 'english', 2, 'Hear and pick out words with br, the weak vowel and the long e, a and o sounds', ARRAY['ENGL.G2.LISTEN.T8_PRONUNCIATION_AND_VO.a', 'ENGL.G2.READIN.T8_FLUENCY.a']::text[], 'The child hears and picks out words with br, /ə/ (the weak sound at the start of about and the end of teacher), /iː/, /eɪ/ and /əʊ/ in a sentence or conversation (for example brush, teacher, read, table, chalk) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.CARDINAL_ORDINAL', 'ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL', 'english', 2, 'Tell and use counting numbers and order numbers', ARRAY['ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.a', 'ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.b']::text[], 'The child tells counting numbers (one, two, three) from order numbers (first, second, third) and uses each in the right place: I have two pencils; I was second in the race; first, second, third, fourth, fifth. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["first or one","what position","fill the gap"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.THESE_THOSE', 'ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL', 'english', 2, 'Use these and those for things near and far', ARRAY['ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.c']::text[], 'The child uses these for more than one thing near (these books) and those for more than one thing far (those trees), with a plural noun. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["these or those","this or these","fill the gap"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.WRITIN.T8_SPELLING.SPELL_VOWEL_TEAMS', 'ENGL.G2.WRITIN.T8_SPELLING', 'english', 2, 'Spell words with br and the long e, a and o sounds', ARRAY['ENGL.G2.WRITIN.T8_SPELLING.a']::text[], 'The child spells classroom words with br and vowel teams (brush, teacher, read, chalk, table, board) and does not write a long vowel with one letter (red for read). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct spelling","fill in the missing letters","spot the wrong spelling"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T9_PRONUNCIATION_AND_VO.CR_ER_Y_AR', 'ENGL.G2.LISTEN.T9_PRONUNCIATION_AND_VO', 'english', 2, 'Hear and pick out words with cr, er, the long a and i sounds, y as ee and ar', ARRAY['ENGL.G2.LISTEN.T9_PRONUNCIATION_AND_VO.a', 'ENGL.G2.READIN.T9_FLUENCY.a']::text[], 'The child hears and picks out words with cr, /ɜː/ (bird, her), /eɪ/, /aɪ/, y said /i/ (happy) and ar in a sentence or conversation (for example cow, crop, bird, hay, sky, puppy, farmer) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.READIN.T9_COMPREHENSION.SETTING', 'ENGL.G2.READIN.T9_COMPREHENSION', 'english', 2, 'Say where and when a story happens', ARRAY['ENGL.G2.READIN.T9_COMPREHENSION.b', 'ENGL.G2.READIN.T14_COMPREHENSION.b']::text[], 'The child names the place and time of a story (on the farm, early in the morning) from the words and pictures. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["where does it happen","when does it happen","which picture shows the setting"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.READIN.T9_COMPREHENSION.MAIN_IDEA', 'ENGL.G2.READIN.T9_COMPREHENSION', 'english', 2, 'Say what a text is mainly about', ARRAY['ENGL.G2.READIN.T9_COMPREHENSION.a']::text[], 'The child chooses what the whole text is about, not one detail, and says whether it tells a story or gives facts. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what is the text about","choose the best title","why was it written"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.READIN.T9_COMPREHENSION.RETELL_IN_ORDER', 'ENGL.G2.READIN.T9_COMPREHENSION', 'english', 2, 'Retell the events of a text in order in his or her own words', ARRAY['ENGL.G2.READIN.T9_COMPREHENSION.c']::text[], 'The child retells three or four events in the order they happened, in own words, using first, next, then and last. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["tell me what happened","retell with first, next, last","tell your partner the story"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LANGUA.T9_WORD_SETS_GENDER_SET.GENDER_PAIRS', 'ENGL.G2.LANGUA.T9_WORD_SETS_GENDER_SET', 'english', 2, 'Use male and female word pairs for people and animals', ARRAY['ENGL.G2.LANGUA.T9_WORD_SETS_GENDER_SET.a', 'ENGL.G2.LANGUA.T9_WORD_SETS_GENDER_SET.b']::text[], 'The child gives and uses gender pairs of the farm and home: cock and hen, bull and cow, ram and ewe, boy and girl, uncle and aunt, king and queen, lion and lioness. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what is the female","match the pairs","fill the gap"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.WRITIN.T9_PUNCTUATION_THE_COMM.COMMA_LIST', 'ENGL.G2.WRITIN.T9_PUNCTUATION_THE_COMM', 'english', 2, 'Use commas in a list', ARRAY['ENGL.G2.WRITIN.T9_PUNCTUATION_THE_COMM.a', 'ENGL.G2.WRITIN.T9_PUNCTUATION_THE_COMM.b']::text[], 'The child finds commas in a text and writes a list of farm things with a comma between items and and before the last (cows, goats, hens and ducks). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["put in the commas","which sentence is right","write the list"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T10_PRONUNCIATION_AND_VO.EAR_ER_DR_OI_IE', 'ENGL.G2.LISTEN.T10_PRONUNCIATION_AND_VO', 'english', 2, 'Hear and pick out words with ear, er, dr, oi and the long i sound', ARRAY['ENGL.G2.LISTEN.T10_PRONUNCIATION_AND_VO.a', 'ENGL.G2.READIN.T10_FLUENCY.a']::text[], 'The child hears and picks out words with /ɪə/, /ə/, /ɜː/, dr, /ɔɪ/ (boy, coin) and /aɪ/ in a sentence or conversation (for example near, turn, drive, point, right) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.READIN.T10_COMPREHENSION.MENTAL_PICTURE', 'ENGL.G2.READIN.T10_COMPREHENSION', 'english', 2, 'Picture characters, places and events from the words', ARRAY['ENGL.G2.READIN.T10_COMPREHENSION.d']::text[], 'The child uses the describing words to picture a character, place or event and chooses or draws the picture that matches every detail. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which picture matches","draw what you read","what would you see"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LANGUA.T10_PREPOSITIONS.PREPOSITIONS', 'ENGL.G2.LANGUA.T10_PREPOSITIONS', 'english', 2, 'Use beside, above, over, below, across, to and at', ARRAY['ENGL.G2.LANGUA.T10_PREPOSITIONS.a', 'ENGL.G2.LANGUA.T10_PREPOSITIONS.b']::text[], 'The child picks the target prepositions in an oral text and uses them to describe where things are and where they go: the bird flew over the house; the lamp is above the table; we walked across the road to the shop. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["where is it","choose the word","describe the picture"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.WRITIN.T10_PUNCTUATION_THE_EXCL.EXCLAMATION_MARK', 'ENGL.G2.WRITIN.T10_PUNCTUATION_THE_EXCL', 'english', 2, 'Recognise and use the exclamation mark', ARRAY['ENGL.G2.WRITIN.T10_PUNCTUATION_THE_EXCL.a', 'ENGL.G2.WRITIN.T10_PUNCTUATION_THE_EXCL.b']::text[], 'The child finds exclamation marks in a text and uses one at the end of a sentence that shows a strong feeling or a warning (Stop! Look out!), not after ordinary sentences. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which mark goes at the end","correct the sentence","where does it go"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T11_PRONUNCIATION_AND_VO.FR_OW_OR_SCHWA', 'ENGL.G2.LISTEN.T11_PRONUNCIATION_AND_VO', 'english', 2, 'Hear and pick out words with fr, ow, or and the weak vowel', ARRAY['ENGL.G2.LISTEN.T11_PRONUNCIATION_AND_VO.a', 'ENGL.G2.READIN.T11_FLUENCY.a']::text[], 'The child hears and picks out words with fr, /aʊ/ (cow, flower), /ɔː/ (forest, warm) and /ə/ in a sentence or conversation (for example fruit, flower, forest, water) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.READIN.T11_FLUENCY.PHRASE_READING', 'ENGL.G2.READIN.T11_FLUENCY', 'english', 2, 'Read in phrases instead of word by word', ARRAY['ENGL.G2.READIN.T11_FLUENCY.b']::text[], 'The child reads groups of words together (in the morning / we went / to the forest) instead of stopping after every word. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["read in scoops","read the sentence smoothly","echo reading"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LANGUA.T11_REGULAR_COMPARATIVE_.COMPARE_ER_EST', 'ENGL.G2.LANGUA.T11_REGULAR_COMPARATIVE_', 'english', 2, 'Compare with -er and -est', ARRAY['ENGL.G2.LANGUA.T11_REGULAR_COMPARATIVE_.a', 'ENGL.G2.LANGUA.T11_REGULAR_COMPARATIVE_.b']::text[], 'The child finds -er and -est words in a text and uses -er than for two (the river is cleaner than the pond) and the -est for more (the tallest tree), with big, bigger spelt right. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.WRITIN.T11_GUIDED_WRITING.WRITE_SENTENCES', 'ENGL.G2.WRITIN.T11_GUIDED_WRITING', 'english', 2, 'Write simple sentences with theme words', ARRAY['ENGL.G2.WRITIN.T11_GUIDED_WRITING.b', 'ENGL.G2.WRITIN.T14_GUIDED_WRITING.b']::text[], 'The child writes two or three short sentences about the theme, each with a capital letter, a doing word and a full stop. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a sentence with the word","write two sentences about","finish the sentence"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T12_PRONUNCIATION_AND_VO.GR_PR_OI_OO_U', 'ENGL.G2.LISTEN.T12_PRONUNCIATION_AND_VO', 'english', 2, 'Hear and pick out words with gr, pr, oi and the long and short oo sounds', ARRAY['ENGL.G2.LISTEN.T12_PRONUNCIATION_AND_VO.a', 'ENGL.G2.READIN.T12_FLUENCY.a']::text[], 'The child hears and picks out words with gr, pr, /ɔɪ/, /uː/ (food, computer) and /ʊ/ (book, put) in a sentence or conversation (for example grow, press, toy, phone screen, book) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LANGUA.T12_POSSESSIVE_PRONOUNS.POSSESSIVE_PRONOUNS', 'ENGL.G2.LANGUA.T12_POSSESSIVE_PRONOUNS', 'english', 2, 'Use mine, yours, ours, hers and his', ARRAY['ENGL.G2.LANGUA.T12_POSSESSIVE_PRONOUNS.a', 'ENGL.G2.LANGUA.T12_POSSESSIVE_PRONOUNS.b']::text[], 'The child finds mine, yours, ours, hers and his in a text and uses them on their own (The phone is mine), his for a boy and hers for a girl, with no apostrophe. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.WRITIN.T12_GUIDED_WRITING.PICTURE_NAMES', 'ENGL.G2.WRITIN.T12_GUIDED_WRITING', 'english', 2, 'Name the objects in pictures', ARRAY['ENGL.G2.WRITIN.T12_GUIDED_WRITING.a']::text[], 'The child names the objects in theme pictures in English (radio, phone, computer, television) and writes each name spelt correctly. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what is in the picture","match the word to the picture","write the name"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.WRITIN.T12_GUIDED_WRITING.PICTURE_SENTENCES', 'ENGL.G2.WRITIN.T12_GUIDED_WRITING', 'english', 2, 'Write sentences from picture prompts', ARRAY['ENGL.G2.WRITIN.T12_GUIDED_WRITING.b']::text[], 'The child writes one full sentence about what is happening in each picture, using the names of the things in it. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a sentence about the picture","what is happening","one sentence for each picture"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T13_BY_THE_END_OF_THE_SU.TR_SM_CH_OW_U', 'ENGL.G2.LISTEN.T13_BY_THE_END_OF_THE_SU', 'english', 2, 'Hear and pick out words with tr, sm, ch, ow and the you sound', ARRAY['ENGL.G2.LISTEN.T13_BY_THE_END_OF_THE_SU.a', 'ENGL.G2.READIN.T13_FLUENCY.a']::text[], 'The child hears and picks out words with tr, sm, /tʃ/, /aʊ/ and /juː/ (music, tune) in a sentence or conversation (for example drum, smile, church, crowd, music) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LANGUA.T13_WH_QUESTIONS.WH_QUESTIONS', 'ENGL.G2.LANGUA.T13_WH_QUESTIONS', 'english', 2, 'Ask questions with what, where, when and who', ARRAY['ENGL.G2.LANGUA.T13_WH_QUESTIONS.a', 'ENGL.G2.LANGUA.T13_WH_QUESTIONS.b']::text[], 'The child recognises what, where, when and who questions and asks them in the right order with a question mark: Where is the dance? When did they sing? Who beat the drum? Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the question word","ask the question","put the words in order"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.WRITIN.T13_GUIDED_WRITING.WORD_ORDER', 'ENGL.G2.WRITIN.T13_GUIDED_WRITING', 'english', 2, 'Put jumbled words in order to make a sentence', ARRAY['ENGL.G2.WRITIN.T13_GUIDED_WRITING.a', 'ENGL.G2.WRITIN.T13_GUIDED_WRITING.b']::text[], 'The child rearranges jumbled words or phrases into a sentence that makes sense, starting with the capital-letter word and ending with the word before the full stop. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["put the words in order","which sentence is right","rearrange the words"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T14_PRONUNCIATION_AND_VO.K_SN_SP_U', 'ENGL.G2.LISTEN.T14_PRONUNCIATION_AND_VO', 'english', 2, 'Hear and pick out words with the k sound, sn, sp and u', ARRAY['ENGL.G2.LISTEN.T14_PRONUNCIATION_AND_VO.a', 'ENGL.G2.READIN.T14_FLUENCY.a']::text[], 'The child hears and picks out words with /k/ (spelt c, k or ck), sn, sp and u (as in cup and put) in a sentence or conversation (for example cook, kitchen, snack, spoon, run) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LANGUA.T14_ADVERBS_OF_TIME.ADVERBS_TIME', 'ENGL.G2.LANGUA.T14_ADVERBS_OF_TIME', 'english', 2, 'Use adverbs of time: soon, late, now, today, tomorrow, early', ARRAY['ENGL.G2.LANGUA.T14_ADVERBS_OF_TIME.a', 'ENGL.G2.LANGUA.T14_ADVERBS_OF_TIME.b']::text[], 'The child finds the adverbs of time in a text and uses them with the right tense: Tomorrow I will help; Today I am cooking; He came late; We woke up early. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.WRITIN.T14_GUIDED_WRITING.RECOUNT_EVENTS', 'ENGL.G2.WRITIN.T14_GUIDED_WRITING', 'english', 2, 'Write a short sequence of three or four events from a story', ARRAY['ENGL.G2.WRITIN.T14_GUIDED_WRITING.c']::text[], 'The child writes three or four sentences that tell events, actions or feelings from a story in order, using first, next, then and last, in the past tense. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write what happened","write it in order","first, next, then, last"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LISTEN.T15_PRONUNCIATION_AND_VO.SCR_SPR_STR_SW_ST', 'ENGL.G2.LISTEN.T15_PRONUNCIATION_AND_VO', 'english', 2, 'Hear and pick out words with scr, spr, str, sw and st', ARRAY['ENGL.G2.LISTEN.T15_PRONUNCIATION_AND_VO.a', 'ENGL.G2.READIN.T15_FLUENCY.a']::text[], 'The child hears and picks out words with scr, spr, str, sw and st in a sentence or conversation (for example scrub, spray, strong, sweep, stop) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.COMMANDS', 'ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS', 'english', 2, 'Recognise, follow and give simple commands', ARRAY['ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.a', 'ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.b', 'ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.c']::text[], 'The child picks commands in a text, does what a command says, and gives commands that start with a plain verb (Sit down. Please close the window.), politely. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which sentence is a command","what should you do","give the command"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.EXCITEMENT_WORDS', 'ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS', 'english', 2, 'Use interjections of excitement and joy', ARRAY['ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.d']::text[], 'The child uses Hurray!, Wow! and Yes! for joy and excitement, in the right place, with an exclamation mark. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word shows joy","complete with an interjection","choose the right word"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G2.WRITIN.T15_GUIDED_WRITING.PUNCTUATE_SENTENCES', 'ENGL.G2.WRITIN.T15_GUIDED_WRITING', 'english', 2, 'Write well-punctuated sentences', ARRAY['ENGL.G2.WRITIN.T15_GUIDED_WRITING.a', 'ENGL.G2.WRITIN.T15_GUIDED_WRITING.b']::text[], 'The child chooses and uses capital letters (sentence starts, names, I), full stops, question marks and exclamation marks correctly in sentences about caring for others. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which mark goes here","correct the sentence","choose the right sentence"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
