INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.BL_SP_SC_SK_CK.M2_SC_SK_DIFFERENT', 'ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.BL_SP_SC_SK_CK', 'Thinks sc and sk say different sounds.', '{"question":"Which two words start with the same sound: scarf, skirt, shirt?","wrong_answer":"scarf and shirt","correct_answer":"scarf and skirt"}'::jsonb, 'The letters look different, so the child expects different sounds.', 'Offer "scarf and shirt" beside "scarf and skirt" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sc and sk both say s-k: scarf, skirt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.BL_SP_SC_SK_CK.M2_BL_TWO_BEATS', 'ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.BL_SP_SC_SK_CK', 'Hears a vowel between b and l.', '{"question":"Clap the beats in \"black\".","wrong_answer":"2 (bu-lack)","correct_answer":"1"}'::jsonb, 'Bantu languages build syllables that end in a vowel.', 'Offer "2 (bu-lack)" beside "1" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'B and l glued together: black, one clap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.BL_SP_SC_SK_CK.M2_SP_FIRST_LETTER', 'ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.BL_SP_SC_SK_CK', 'Picks any word that starts with s for sp.', '{"question":"Which word starts with sp: sun, spoon, soap?","wrong_answer":"sun","correct_answer":"spoon"}'::jsonb, 'Only the first letter is listened for.', 'Offer "sun" beside "spoon" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen for the second sound: s-p.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.BL_SP_SC_SK_CK.M2_CK_VOICED', 'ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.BL_SP_SC_SK_CK', 'Hears the ck at the end as g.', '{"question":"The teacher says \"back\". Back or bag?","wrong_answer":"bag","correct_answer":"back"}'::jsonb, 'Voiceless and voiced sounds at the end are not told apart.', 'Offer "bag" beside "back" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ck is a click with no buzz: back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS.M2_TW_SAME_GROUP', 'ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS', 'Picks a word from the same group but not the right one.', '{"question":"We use a ... to clean the chalkboard.","wrong_answer":"broom","correct_answer":"duster"}'::jsonb, 'The child knows the group (cleaning things) but not the exact word.', 'Offer "broom" beside "duster" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Think what this one is used for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS.M2_TW_HOME_WORD', 'ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS', 'Uses a Kiswahili word in an English sentence.', '{"question":"We travelled to town by ...","wrong_answer":"gari","correct_answer":"car (or matatu)"}'::jsonb, 'The home word comes first to mind.', 'Offer "gari" beside "car (or matatu)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say it in English.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS.M2_TW_SOUND_ALIKE', 'ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS', 'Picks a word that sounds like the right one.', '{"question":"Mama bought sugar at the ...","wrong_answer":"shop keeper","correct_answer":"shop"}'::jsonb, 'The child matches part of a word heard in the lesson.', 'Offer "shop keeper" beside "shop" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read the sentence with it: does it make sense?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS.M2_TW_PERSON_THING', 'ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS', 'Uses a thing word for a person.', '{"question":"The person who sells things in a shop is a ...","wrong_answer":"shop","correct_answer":"shopkeeper"}'::jsonb, 'Person and place words are learnt together.', 'Offer "shop" beside "shopkeeper" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A person does it; a place is where it happens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.FOLLOW_TWO_STEP.M2_FI_LAST_ONLY', 'ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.FOLLOW_TWO_STEP', 'Does only the second step.', '{"question":"Stand up and close the door.","wrong_answer":"closes the door while sitting","correct_answer":"stands up, then closes the door"}'::jsonb, 'The last step is freshest.', 'Offer "closes the door while sitting" beside "stands up, then closes the door" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Hold up two fingers as you listen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.FOLLOW_TWO_STEP.M2_FI_ORDER', 'ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.FOLLOW_TWO_STEP', 'Does the steps in the wrong order.', '{"question":"Wash your hands, then eat your snack.","wrong_answer":"eats, then washes","correct_answer":"washes, then eats"}'::jsonb, 'Then is not yet heard as an order word.', 'Offer "eats, then washes" beside "washes, then eats" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Then means after.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.FOLLOW_TWO_STEP.M2_FI_LEFT_RIGHT', 'ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.FOLLOW_TWO_STEP', 'Mixes left and right.', '{"question":"Raise your right hand and touch your left ear.","wrong_answer":"raises the left hand","correct_answer":"right hand up, left ear touched"}'::jsonb, 'Left and right are not yet secure.', 'Offer "raises the left hand" beside "right hand up, left ear touched" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Hold both hands up, palms out, thumbs apart: the left hand makes an L.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.FOLLOW_TWO_STEP.M2_FI_COPY', 'ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.FOLLOW_TWO_STEP', 'Watches a classmate instead of listening.', '{"question":"Pick up a red crayon and colour the sun.","wrong_answer":"picks the colour a friend picked","correct_answer":"red crayon, colours the sun"}'::jsonb, 'The child relies on others when unsure of the words.', 'Offer "picks the colour a friend picked" beside "red crayon, colours the sun" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen with your eyes closed, then do it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T1_FLUENCY.READ_ACCURATELY.M2_RA_GUESS', 'ENGL.G2.READIN.T1_FLUENCY.READ_ACCURATELY', 'Guesses a word from its first letter or the picture.', '{"question":"Read: The goat is in the garden.","wrong_answer":"The goat is in the grass.","correct_answer":"The goat is in the garden."}'::jsonb, 'Sight-word guessing: the picture shows grass and the word starts with g.', 'Offer "The goat is in the grass." beside "The goat is in the garden." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look at every letter: g-ar-d-e-n.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T1_FLUENCY.READ_ACCURATELY.M2_RA_B_D', 'ENGL.G2.READIN.T1_FLUENCY.READ_ACCURATELY', 'Reads b as d or d as b.', '{"question":"Read: The dog has a bone.","wrong_answer":"The bog has a done.","correct_answer":"The dog has a bone."}'::jsonb, 'B and d are mirror shapes and are still mixed at this age.', 'Offer "The bog has a done." beside "The dog has a bone." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Make a bed with your fists: b first, d last.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T1_FLUENCY.READ_ACCURATELY.M2_RA_SKIP', 'ENGL.G2.READIN.T1_FLUENCY.READ_ACCURATELY', 'Skips small words.', '{"question":"Read: We go to the market on Saturday.","wrong_answer":"We go market Saturday.","correct_answer":"We go to the market on Saturday."}'::jsonb, 'Small words carry little meaning for the child.', 'Offer "We go market Saturday." beside "We go to the market on Saturday." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Point under every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T1_FLUENCY.READ_ACCURATELY.M2_RA_ADDS', 'ENGL.G2.READIN.T1_FLUENCY.READ_ACCURATELY', 'Adds words that are not there.', '{"question":"Read: Mama bought tomatoes.","wrong_answer":"My mama bought some tomatoes.","correct_answer":"Mama bought tomatoes."}'::jsonb, 'The child says what sounds natural instead of what is written.', 'Offer "My mama bought some tomatoes." beside "Mama bought tomatoes." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read only what your finger touches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T1_COMPREHENSION.PREDICT.M2_PR_DESCRIBE', 'ENGL.G2.READIN.T1_COMPREHENSION.PREDICT', 'Describes the picture instead of predicting.', '{"question":"Title: The Lost Goat. Picture: a girl calling. What will happen?","wrong_answer":"A girl is calling.","correct_answer":"She will find her goat."}'::jsonb, 'The child answers what is seen.', 'Offer "A girl is calling." beside "She will find her goat." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say what will happen, with will.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T1_COMPREHENSION.PREDICT.M2_PR_NO_CLUE', 'ENGL.G2.READIN.T1_COMPREHENSION.PREDICT', 'Predicts without using the title or picture.', '{"question":"Title: Our New Garden. What might the story be about?","wrong_answer":"a football match","correct_answer":"planting a garden"}'::jsonb, 'The first idea is said.', 'Offer "a football match" beside "planting a garden" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use a word from the title.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T1_COMPREHENSION.PREDICT.M2_PR_ALREADY', 'ENGL.G2.READIN.T1_COMPREHENSION.PREDICT', 'Gives what has already happened.', '{"question":"Ali fell off his bicycle. What will happen next?","wrong_answer":"Ali fell off his bicycle.","correct_answer":"Someone will help him up."}'::jsonb, 'Next and before are mixed.', 'Offer "Ali fell off his bicycle." beside "Someone will help him up." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Next means after what we read.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T1_COMPREHENSION.PREDICT.M2_PR_AFRAID', 'ENGL.G2.READIN.T1_COMPREHENSION.PREDICT', 'Will not guess in case it is wrong.', '{"question":"Is it wrong to guess what happens next?","wrong_answer":"Yes, it is wrong.","correct_answer":"No. Good readers guess, then check."}'::jsonb, 'Fear of a wrong answer.', 'Offer "Yes, it is wrong." beside "No. Good readers guess, then check." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Guess, then check.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T1_COMPREHENSION.WORD_FROM_CONTEXT.M2_WC_LOOKS_LIKE', 'ENGL.G2.READIN.T1_COMPREHENSION.WORD_FROM_CONTEXT', 'Picks a word that looks like the new word.', '{"question":"The farmer fed the calf. A calf is ...","wrong_answer":"a cliff","correct_answer":"a young cow"}'::jsonb, 'Letters are matched, not meaning.', 'Offer "a cliff" beside "a young cow" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Does that meaning fit the sentence?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T1_COMPREHENSION.WORD_FROM_CONTEXT.M2_WC_GIVE_UP', 'ENGL.G2.READIN.T1_COMPREHENSION.WORD_FROM_CONTEXT', 'Says the word cannot be known.', '{"question":"The road was muddy after the rain. Muddy means ...","wrong_answer":"I do not know.","correct_answer":"wet and dirty with soil"}'::jsonb, 'The child does not know the sentence gives clues.', 'Offer "I do not know." beside "wet and dirty with soil" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look for clues: after the rain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T1_COMPREHENSION.WORD_FROM_CONTEXT.M2_WC_PICTURE_ONLY', 'ENGL.G2.READIN.T1_COMPREHENSION.WORD_FROM_CONTEXT', 'Uses only the picture.', '{"question":"Picture: a boy and a dog. \"The boy was scared of the barking dog.\" Scared means ...","wrong_answer":"happy","correct_answer":"afraid"}'::jsonb, 'The picture shows a boy smiling earlier.', 'Offer "happy" beside "afraid" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read the words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T1_COMPREHENSION.WORD_FROM_CONTEXT.M2_WC_USUAL_MEANING', 'ENGL.G2.READIN.T1_COMPREHENSION.WORD_FROM_CONTEXT', 'Gives the usual meaning when the word means something else here.', '{"question":"Please turn left at the shop. Here left means ...","wrong_answer":"went away","correct_answer":"the side opposite right"}'::jsonb, 'The meaning known best is used.', 'Offer "went away" beside "the side opposite right" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Which meaning fits here?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T1_COMPREHENSION.DIRECT_QUESTIONS.M2_DQ_OWN_LIFE', 'ENGL.G2.READIN.T1_COMPREHENSION.DIRECT_QUESTIONS', 'Answers from home, not from the text.', '{"question":"Text: Akinyi ate an orange. What did Akinyi eat?","wrong_answer":"a mango","correct_answer":"an orange"}'::jsonb, 'The child answers what is usual at home.', 'Offer "a mango" beside "an orange" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Point to the answer in the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T1_COMPREHENSION.DIRECT_QUESTIONS.M2_DQ_WRONG_WORD', 'ENGL.G2.READIN.T1_COMPREHENSION.DIRECT_QUESTIONS', 'Gives the wrong kind of answer.', '{"question":"Text: We went to the farm on Sunday. When did we go?","wrong_answer":"to the farm","correct_answer":"on Sunday"}'::jsonb, 'Question words are not matched to answers.', 'Offer "to the farm" beside "on Sunday" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'When wants a time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T1_COMPREHENSION.DIRECT_QUESTIONS.M2_DQ_WORD_MATCH', 'ENGL.G2.READIN.T1_COMPREHENSION.DIRECT_QUESTIONS', 'Copies a sentence that shares a word with the question.', '{"question":"Text: The hen laid an egg. The cow ate grass. What did the cow eat?","wrong_answer":"The hen laid an egg.","correct_answer":"grass"}'::jsonb, 'A word is matched, not the meaning.', 'Offer "The hen laid an egg." beside "grass" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Find the sentence about the cow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T1_COMPREHENSION.DIRECT_QUESTIONS.M2_DQ_YES_NO', 'ENGL.G2.READIN.T1_COMPREHENSION.DIRECT_QUESTIONS', 'Answers yes or no to a what question.', '{"question":"Text: Tom has a red ball. What colour is the ball?","wrong_answer":"Yes.","correct_answer":"red"}'::jsonb, 'Every question is treated as yes or no.', 'Offer "Yes." beside "red" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'What colour wants a colour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.WAS_WERE.M2_WW_WE_WAS', 'ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.WAS_WERE', 'Uses was with we, you or they.', '{"question":"Yesterday we ... in the library.","wrong_answer":"was","correct_answer":"were"}'::jsonb, 'Was is learnt first and used for every past.', 'Offer "was" beside "were" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'We, you, they: were.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.WAS_WERE.M2_WW_I_WERE', 'ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.WAS_WERE', 'Uses were with I, he or she.', '{"question":"Juma ... late for school.","wrong_answer":"were","correct_answer":"was"}'::jsonb, 'Were is over-used once learnt.', 'Offer "were" beside "was" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One person: was.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.WAS_WERE.M2_WW_IS_PAST', 'ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.WAS_WERE', 'Uses is or are for the past.', '{"question":"Last week the classroom ... dirty.","wrong_answer":"is","correct_answer":"was"}'::jsonb, 'The present form is used for all times.', 'Offer "is" beside "was" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Last week: was.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.WAS_WERE.M2_WW_CHILDREN_WAS', 'ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.WAS_WERE', 'Uses was with a plural noun without -s.', '{"question":"The children ... happy.","wrong_answer":"was","correct_answer":"were"}'::jsonb, 'Children does not end in -s.', 'Offer "was" beside "were" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Children is more than one: were.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.OBJECT_PRONOUNS.M2_OP_WE_FOR_US', 'ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.OBJECT_PRONOUNS', 'Uses we after a verb.', '{"question":"The teacher gave ... sweets.","wrong_answer":"we","correct_answer":"us"}'::jsonb, 'We and us mean the same people.', 'Offer "we" beside "us" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After the verb: us.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.OBJECT_PRONOUNS.M2_OP_THEY_FOR_THEM', 'ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.OBJECT_PRONOUNS', 'Uses they after a verb.', '{"question":"I saw ... at the market.","wrong_answer":"they","correct_answer":"them"}'::jsonb, 'They and them are mixed.', 'Offer "they" beside "them" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After the verb: them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.OBJECT_PRONOUNS.M2_OP_US_SUBJECT', 'ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.OBJECT_PRONOUNS', 'Uses us or them as the subject.', '{"question":"... went to the field. (we)","wrong_answer":"Us","correct_answer":"We"}'::jsonb, 'The object form is heard often and used everywhere.', 'Offer "Us" beside "We" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'At the start, doing the action: we.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.OBJECT_PRONOUNS.M2_OP_PREP_THEY', 'ENGL.G2.LANGUA.T1_VERB_TO_BE_PAST_TENS.OBJECT_PRONOUNS', 'Uses they after with or to.', '{"question":"Come and play with ...","wrong_answer":"they","correct_answer":"them"}'::jsonb, 'The subject form is used after small words.', 'Offer "they" beside "them" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After with and to: them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T1_HANDWRITING.DESCENDERS.M2_DE_ON_LINE', 'ENGL.G2.WRITIN.T1_HANDWRITING.DESCENDERS', 'Sits g, p or y on the line with no tail below.', '{"question":"Where does the tail of g go?","wrong_answer":"on the line","correct_answer":"below the line"}'::jsonb, 'All letters are thought to sit on the line.', 'Offer "on the line" beside "below the line" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tails hang below like roots.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T1_HANDWRITING.DESCENDERS.M2_DE_TALL', 'ENGL.G2.WRITIN.T1_HANDWRITING.DESCENDERS', 'Thinks p or q reaches up.', '{"question":"Which letter hangs down: b, p, d?","wrong_answer":"b","correct_answer":"p"}'::jsonb, 'B and p are the same shape flipped.', 'Offer "b" beside "p" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'P hangs down; b reaches up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T1_HANDWRITING.DESCENDERS.M2_DE_J_I', 'ENGL.G2.WRITIN.T1_HANDWRITING.DESCENDERS', 'Writes j with no tail, like i.', '{"question":"Which is the letter j?","wrong_answer":"a dot over a short stick on the line","correct_answer":"a dot over a stick with a hook below the line"}'::jsonb, 'J and i are learnt together.', 'Offer "a dot over a short stick on the line" beside "a dot over a stick with a hook below the line" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'J has a tail with a hook.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T1_HANDWRITING.DESCENDERS.M2_DE_CAPITAL', 'ENGL.G2.WRITIN.T1_HANDWRITING.DESCENDERS', 'Uses a capital G or Y inside a word to avoid the tail.', '{"question":"Write: dog","wrong_answer":"doG","correct_answer":"dog"}'::jsonb, 'Capitals sit on the line and feel easier.', 'Offer "doG" beside "dog" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Inside a word: small g with its tail.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T1_HANDWRITING.HANDWRITING_NEAT.M2_HN_CAPS_INSIDE', 'ENGL.G2.WRITIN.T1_HANDWRITING.HANDWRITING_NEAT', 'Mixes capitals inside words.', '{"question":"Copy: classroom","wrong_answer":"clAssRoom","correct_answer":"classroom"}'::jsonb, 'Some capitals are easier to form.', 'Offer "clAssRoom" beside "classroom" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'All small letters inside a word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T1_HANDWRITING.HANDWRITING_NEAT.M2_HN_SIZE', 'ENGL.G2.WRITIN.T1_HANDWRITING.HANDWRITING_NEAT', 'Writes letters of very different sizes.', '{"question":"Copy: teacher","wrong_answer":"letters jumping up and down in size","correct_answer":"even small letters"}'::jsonb, 'Letters are formed one at a time.', 'Offer "letters jumping up and down in size" beside "even small letters" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Small letters fill half the space.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T1_HANDWRITING.HANDWRITING_NEAT.M2_HN_OPEN', 'ENGL.G2.WRITIN.T1_HANDWRITING.HANDWRITING_NEAT', 'Leaves round letters open (a like u, d like cl).', '{"question":"Copy: dad","wrong_answer":"cl a cl","correct_answer":"dad"}'::jsonb, 'Round letters are started at the bottom.', 'Offer "cl a cl" beside "dad" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start at the top like c, go round, close it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T1_HANDWRITING.HANDWRITING_NEAT.M2_HN_RIGHT_TO_LEFT', 'ENGL.G2.WRITIN.T1_HANDWRITING.HANDWRITING_NEAT', 'Starts some letters on the wrong side, so they come out reversed.', '{"question":"Copy: bed","wrong_answer":"deb","correct_answer":"bed"}'::jsonb, 'The direction of the stroke is not fixed.', 'Offer "deb" beside "bed" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'B starts with the stick, then the belly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.CH_OA_SH_CL.M2_CH_SH', 'ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.CH_OA_SH_CL', 'Hears ch as sh.', '{"question":"Which word starts with the sound in chair: shop, chop, sop?","wrong_answer":"shop","correct_answer":"chop"}'::jsonb, 'A home language with sh and no ch, or the reverse.', 'Offer "shop" beside "chop" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ch starts with a stop: t-sh.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.CH_OA_SH_CL.M2_SH_S', 'ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.CH_OA_SH_CL', 'Hears sh as s.', '{"question":"The teacher says \"ship\". Ship or sip?","wrong_answer":"sip","correct_answer":"ship"}'::jsonb, 'Some home languages have no sh.', 'Offer "sip" beside "ship" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sh: round lips, shhh.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.CH_OA_SH_CL.M2_OA_SHORT_O', 'ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.CH_OA_SH_CL', 'Hears the long o (home, boat) as the short o of hot.', '{"question":"The teacher says \"coat\". Coat or cot?","wrong_answer":"cot","correct_answer":"coat"}'::jsonb, 'Five-vowel home languages have one o sound.', 'Offer "cot" beside "coat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Long o slides: o-oo, coat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.CH_OA_SH_CL.M2_CL_CR', 'ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.CH_OA_SH_CL', 'Hears cl as cr.', '{"question":"The teacher says \"clown\". Clown or crown?","wrong_answer":"crown","correct_answer":"clown"}'::jsonb, 'L and r are merged in some home languages.', 'Offer "crown" beside "clown" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tongue up for l: clown.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.SAY_CONSONANT_SOUNDS.M2_SCS_EXTRA_VOWEL', 'ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.SAY_CONSONANT_SOUNDS', 'Slips a vowel into a blend.', '{"question":"Say: blue","wrong_answer":"bulu","correct_answer":"blue"}'::jsonb, 'Bantu languages build syllables that end in a vowel.', 'Offer "bulu" beside "blue" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Glue the consonants: blue, one beat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.SAY_CONSONANT_SOUNDS.M2_SCS_L_R', 'ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.SAY_CONSONANT_SOUNDS', 'Says l for r, or r for l.', '{"question":"Say: The lorry is red.","wrong_answer":"The rorry is led.","correct_answer":"The lorry is red."}'::jsonb, 'L and r merged.', 'Offer "The rorry is led." beside "The lorry is red." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tongue up for l, curled back for r.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.SAY_CONSONANT_SOUNDS.M2_SCS_TH', 'ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.SAY_CONSONANT_SOUNDS', 'Says th as t or d.', '{"question":"Say: this thing","wrong_answer":"dis ting","correct_answer":"this thing"}'::jsonb, 'Th is missing in most home languages.', 'Offer "dis ting" beside "this thing" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tongue between the teeth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.SAY_CONSONANT_SOUNDS.M2_SCS_SH_S', 'ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.SAY_CONSONANT_SOUNDS', 'Says sh as s.', '{"question":"Say: She washes the dishes.","wrong_answer":"Se wases the dises.","correct_answer":"She washes the dishes."}'::jsonb, 'The home language has no sh.', 'Offer "Se wases the dises." beside "She washes the dishes." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Round lips: shhh.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T2_FLUENCY.READ_WITH_FEELING.M2_RF_FLAT', 'ENGL.G2.READIN.T2_FLUENCY.READ_WITH_FEELING', 'Reads every sentence in the same flat voice.', '{"question":"Read: \"Oh no! My cup is broken!\" cried Achieng.","wrong_answer":"flat voice","correct_answer":"a sad, upset voice"}'::jsonb, 'The child is busy with the words.', 'Offer "flat voice" beside "a sad, upset voice" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'How does Achieng feel? Say it like her.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T2_FLUENCY.READ_WITH_FEELING.M2_RF_NO_STOP', 'ENGL.G2.READIN.T2_FLUENCY.READ_WITH_FEELING', 'Reads through full stops.', '{"question":"Read: The bus came. We got in.","wrong_answer":"The bus came we got in.","correct_answer":"The bus came. (pause) We got in."}'::jsonb, 'Full stops are seen as dots.', 'Offer "The bus came we got in." beside "The bus came. (pause) We got in." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A full stop means stop and breathe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T2_FLUENCY.READ_WITH_FEELING.M2_RF_QUESTION', 'ENGL.G2.READIN.T2_FLUENCY.READ_WITH_FEELING', 'Reads a question like a statement.', '{"question":"Read: Can I help you?","wrong_answer":"voice falls","correct_answer":"voice rises at the end"}'::jsonb, 'Questions at home are marked by a word, not the voice.', 'Offer "voice falls" beside "voice rises at the end" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The question mark says lift your voice.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T2_FLUENCY.READ_WITH_FEELING.M2_RF_WRONG_FEELING', 'ENGL.G2.READIN.T2_FLUENCY.READ_WITH_FEELING', 'Shows a feeling that does not fit.', '{"question":"Read: \"I lost my shilling,\" said Tom sadly.","wrong_answer":"a happy, bouncy voice","correct_answer":"a sad voice"}'::jsonb, 'The child reads with excitement every time to sound good.', 'Offer "a happy, bouncy voice" beside "a sad voice" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look for the feeling word: sadly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T2_COMPREHENSION.INDIRECT_QUESTIONS.M2_IQ_NOT_SAID', 'ENGL.G2.READIN.T2_COMPREHENSION.INDIRECT_QUESTIONS', 'Says the answer is not in the text when clues show it.', '{"question":"Tom smiled and clapped his hands. How did Tom feel?","wrong_answer":"It does not say.","correct_answer":"happy"}'::jsonb, 'Only the exact words are looked for.', 'Offer "It does not say." beside "happy" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Smiling and clapping show happy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T2_COMPREHENSION.INDIRECT_QUESTIONS.M2_IQ_GUESS', 'ENGL.G2.READIN.T2_COMPREHENSION.INDIRECT_QUESTIONS', 'Picks a feeling with no clue.', '{"question":"Amina cried when she fell. How did she feel?","wrong_answer":"sleepy","correct_answer":"hurt and sad"}'::jsonb, 'A feeling is chosen from the child''s own idea.', 'Offer "sleepy" beside "hurt and sad" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'What does crying show?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T2_COMPREHENSION.INDIRECT_QUESTIONS.M2_IQ_TOO_FAR', 'ENGL.G2.READIN.T2_COMPREHENSION.INDIRECT_QUESTIONS', 'Gives an answer the clues do not show.', '{"question":"The ground was wet in the morning. Why?","wrong_answer":"A lorry poured water.","correct_answer":"It rained in the night."}'::jsonb, 'The child goes beyond the clues.', 'Offer "A lorry poured water." beside "It rained in the night." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use the most likely reason.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T2_COMPREHENSION.INDIRECT_QUESTIONS.M2_IQ_COPY', 'ENGL.G2.READIN.T2_COMPREHENSION.INDIRECT_QUESTIONS', 'Copies the question words as the answer.', '{"question":"Why did Ben take an umbrella? (The sky was grey.)","wrong_answer":"Ben took an umbrella.","correct_answer":"because the sky was grey and it might rain"}'::jsonb, 'The repeated words are copied.', 'Offer "Ben took an umbrella." beside "because the sky was grey and it might rain" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The reason is in another sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T2_COMPREHENSION.TEXT_TO_LIFE.M2_TL_OFF_TEXT', 'ENGL.G2.READIN.T2_COMPREHENSION.TEXT_TO_LIFE', 'Tells a home story with no link to the text.', '{"question":"The story is about a boy who helps his mother cook. Is this like your life?","wrong_answer":"I went to Mombasa.","correct_answer":"Yes, I also help my mother cook."}'::jsonb, 'The child follows his or her own thought.', 'Offer "I went to Mombasa." beside "Yes, I also help my mother cook." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say which part of the story is like your life.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T2_COMPREHENSION.TEXT_TO_LIFE.M2_TL_CHANGES_TEXT', 'ENGL.G2.READIN.T2_COMPREHENSION.TEXT_TO_LIFE', 'Changes the story to match home life.', '{"question":"In the story, Juma''s family eats rice. What does Juma''s family eat?","wrong_answer":"ugali, like us","correct_answer":"rice"}'::jsonb, 'Home life is mixed into the text.', 'Offer "ugali, like us" beside "rice" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The text says rice; at home you may eat ugali.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T2_COMPREHENSION.TEXT_TO_LIFE.M2_TL_SAME_ONLY', 'ENGL.G2.READIN.T2_COMPREHENSION.TEXT_TO_LIFE', 'Sees only what is the same and nothing different.', '{"question":"How is the farm in the story different from your home?","wrong_answer":"It is the same.","correct_answer":"The farm has cows; my home has none."}'::jsonb, 'The child looks for matches only.', 'Offer "It is the same." beside "The farm has cows; my home has none." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Find one thing the same and one different.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T2_COMPREHENSION.TEXT_TO_LIFE.M2_TL_ONE_WORD', 'ENGL.G2.READIN.T2_COMPREHENSION.TEXT_TO_LIFE', 'Answers yes or no and stops.', '{"question":"Have you ever been to a market like the one in the story?","wrong_answer":"Yes.","correct_answer":"Yes. I go to the market with my aunt on Saturday."}'::jsonb, 'One word answers the question.', 'Offer "Yes." beside "Yes. I go to the market with my aunt on Saturday." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say when and what you did.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.SUBJECT_PRONOUNS.M2_SP_DOUBLE', 'ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.SUBJECT_PRONOUNS', 'Repeats the subject with a pronoun.', '{"question":"Correct: My mother she cooks rice.","wrong_answer":"My mother she cooks rice.","correct_answer":"My mother cooks rice."}'::jsonb, 'Kiswahili and spoken Kenyan English mark the subject twice.', 'Offer "My mother she cooks rice." beside "My mother cooks rice." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One subject: My mother cooks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.SUBJECT_PRONOUNS.M2_SP_HE_SHE', 'ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.SUBJECT_PRONOUNS', 'Uses he for a girl or she for a boy.', '{"question":"Amina is my friend. ... sweeps the room.","wrong_answer":"He","correct_answer":"She"}'::jsonb, 'Kiswahili yeye means he or she.', 'Offer "He" beside "She" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A girl: she. A boy: he.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.SUBJECT_PRONOUNS.M2_SP_THEM_SUBJECT', 'ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.SUBJECT_PRONOUNS', 'Uses them as the subject.', '{"question":"Ali and Tom are brothers. ... wash the dishes.","wrong_answer":"Them","correct_answer":"They"}'::jsonb, 'Them is heard more often in speech.', 'Offer "Them" beside "They" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'At the start: they.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.SUBJECT_PRONOUNS.M2_SP_US_SUBJECT', 'ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.SUBJECT_PRONOUNS', 'Uses us as the subject.', '{"question":"My sister and I help. ... sweep the house.","wrong_answer":"Us","correct_answer":"We"}'::jsonb, 'Us is heard as the word for me and others.', 'Offer "Us" beside "We" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'At the start: we.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.VERB_DO.M2_DO_HE_DO', 'ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.VERB_DO', 'Uses do with he, she or it.', '{"question":"Baba ... the shopping.","wrong_answer":"do","correct_answer":"does"}'::jsonb, 'The -es of does is not linked to he and she.', 'Offer "do" beside "does" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'He, she, it: does.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.VERB_DO.M2_DO_DID_ED', 'ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.VERB_DO', 'Puts a past verb after did.', '{"question":"Did you ... your bed? (make)","wrong_answer":"made","correct_answer":"make"}'::jsonb, 'The past is shown twice.', 'Offer "made" beside "make" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Did says past: the verb stays plain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.VERB_DO.M2_DO_DOES_PAST', 'ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.VERB_DO', 'Uses does for the past.', '{"question":"Yesterday she ... the washing.","wrong_answer":"does","correct_answer":"did"}'::jsonb, 'One form for all times.', 'Offer "does" beside "did" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Yesterday: did.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.VERB_DO.M2_DO_THEY_DOES', 'ENGL.G2.LANGUA.T2_VERB_TO_DO_PRESENT_A.VERB_DO', 'Uses does with we, you or they.', '{"question":"They ... their homework at night.","wrong_answer":"does","correct_answer":"do"}'::jsonb, 'Does is over-used.', 'Offer "does" beside "do" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'They: do.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T2_HANDWRITING.ASCENDERS.M2_AS_SHORT', 'ENGL.G2.WRITIN.T2_HANDWRITING.ASCENDERS', 'Writes tall letters as short as the others.', '{"question":"Which \"hat\" is right: h and t tall, or all the same height?","wrong_answer":"all the same height","correct_answer":"h and t taller"}'::jsonb, 'Letter heights are not compared.', 'Offer "all the same height" beside "h and t taller" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tall letters touch the top line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T2_HANDWRITING.ASCENDERS.M2_AS_WHICH', 'ENGL.G2.WRITIN.T2_HANDWRITING.ASCENDERS', 'Thinks a short letter is tall.', '{"question":"Which letter is tall: a, k, n?","wrong_answer":"a","correct_answer":"k"}'::jsonb, 'The tall letters are not yet known as a group.', 'Offer "a" beside "k" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'B, d, f, h, k, l and t reach up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T2_HANDWRITING.ASCENDERS.M2_AS_CAPITAL', 'ENGL.G2.WRITIN.T2_HANDWRITING.ASCENDERS', 'Uses a capital to make a letter tall.', '{"question":"Write: bed","wrong_answer":"Bed (in the middle of a sentence)","correct_answer":"bed"}'::jsonb, 'Capitals look tall.', 'Offer "Bed (in the middle of a sentence)" beside "bed" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Small b is already tall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T2_HANDWRITING.ASCENDERS.M2_AS_T_LIKE_L', 'ENGL.G2.WRITIN.T2_HANDWRITING.ASCENDERS', 'Makes t as tall as l, or crosses it at the top.', '{"question":"Which \"little\" is right?","wrong_answer":"t as tall as l, crossed at the top","correct_answer":"t shorter than l, crossed lower"}'::jsonb, 'T is grouped with the tallest letters.', 'Offer "t as tall as l, crossed at the top" beside "t shorter than l, crossed lower" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'T is a little shorter, crossed at the middle line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.S_L_FL_AY.M2_AY_SHORT_E', 'ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.S_L_FL_AY', 'Hears the long a as the short e.', '{"question":"The teacher says \"late\". Late or let?","wrong_answer":"let","correct_answer":"late"}'::jsonb, 'The home language has one e sound.', 'Offer "let" beside "late" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Long a slides: e-ee, late.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.S_L_FL_AY.M2_FL_FR', 'ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.S_L_FL_AY', 'Hears fl as fr.', '{"question":"The teacher says \"fly\". Fly or fry?","wrong_answer":"fry","correct_answer":"fly"}'::jsonb, 'L and r merged.', 'Offer "fry" beside "fly" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tongue up behind the teeth: fly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.S_L_FL_AY.M2_L_R', 'ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.S_L_FL_AY', 'Hears l as r.', '{"question":"The teacher says \"lorry\". Which sound does it start with: l or r?","wrong_answer":"r","correct_answer":"l"}'::jsonb, 'L and r merged.', 'Offer "r" beside "l" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Watch the tongue: up for l.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.S_L_FL_AY.M2_S_SH', 'ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.S_L_FL_AY', 'Hears s as sh, or sh as s.', '{"question":"The teacher says \"seat\". Seat or sheet?","wrong_answer":"sheet","correct_answer":"seat"}'::jsonb, 'S and sh are not kept apart.', 'Offer "sheet" beside "seat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'S: smile and hiss. Sh: round lips.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.USE_WORDS_SENTENCES.M2_UW_ONE_WORD', 'ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.USE_WORDS_SENTENCES', 'Answers with one word.', '{"question":"How did you come to school?","wrong_answer":"Walking.","correct_answer":"I walked to school."}'::jsonb, 'One word answers the question.', 'Offer "Walking." beside "I walked to school." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say it in a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.USE_WORDS_SENTENCES.M2_UW_OPEN_LIGHT', 'ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.USE_WORDS_SENTENCES', 'Translates word for word from Kiswahili.', '{"question":"Ask your brother to put the radio on.","wrong_answer":"Open the radio.","correct_answer":"Please switch on the radio."}'::jsonb, 'Fungua redio said word for word.', 'Offer "Open the radio." beside "Please switch on the radio." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'We switch on radios and lights.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.USE_WORDS_SENTENCES.M2_UW_WRONG_MEANING', 'ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.USE_WORDS_SENTENCES', 'Uses a new word with the wrong meaning.', '{"question":"Use \"early\" in a sentence.","wrong_answer":"I came early, the bell had rung long ago.","correct_answer":"I came early, before the bell."}'::jsonb, 'The word is used before its meaning is secure.', 'Offer "I came early, the bell had rung long ago." beside "I came early, before the bell." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Early means before the time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.USE_WORDS_SENTENCES.M2_UW_ECHO', 'ENGL.G2.LISTEN.T3_PRONUNCIATION_AND_VO.USE_WORDS_SENTENCES', 'Repeats the question as the answer.', '{"question":"What is your favourite month?","wrong_answer":"What is my favourite month.","correct_answer":"My favourite month is December."}'::jsonb, 'The child repeats to buy time.', 'Offer "What is my favourite month." beside "My favourite month is December." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start with My ... is ...', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T3_VERBS_TO_HAVE_OBJECT.VERB_HAVE.M2_HV_HE_HAVE', 'ENGL.G2.LANGUA.T3_VERBS_TO_HAVE_OBJECT.VERB_HAVE', 'Uses have with he, she or it.', '{"question":"Baraka ... a bicycle.","wrong_answer":"have","correct_answer":"has"}'::jsonb, 'Have is learnt first.', 'Offer "have" beside "has" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'He, she, it: has.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T3_VERBS_TO_HAVE_OBJECT.VERB_HAVE.M2_HV_HAVING', 'ENGL.G2.LANGUA.T3_VERBS_TO_HAVE_OBJECT.VERB_HAVE', 'Says am having for have.', '{"question":"I ... a new pencil.","wrong_answer":"am having","correct_answer":"have"}'::jsonb, 'Common Kenyan English.', 'Offer "am having" beside "have" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'For what you own: I have.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T3_VERBS_TO_HAVE_OBJECT.VERB_HAVE.M2_HV_PAST', 'ENGL.G2.LANGUA.T3_VERBS_TO_HAVE_OBJECT.VERB_HAVE', 'Uses has for the past.', '{"question":"Last year we ... a cow.","wrong_answer":"has","correct_answer":"had"}'::jsonb, 'One form for all times.', 'Offer "has" beside "had" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Last year: had.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T3_VERBS_TO_HAVE_OBJECT.VERB_HAVE.M2_HV_WE_HAS', 'ENGL.G2.LANGUA.T3_VERBS_TO_HAVE_OBJECT.VERB_HAVE', 'Uses has with we or they.', '{"question":"We ... a big garden.","wrong_answer":"has","correct_answer":"have"}'::jsonb, 'Has is over-used.', 'Offer "has" beside "have" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'We: have.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.NG_EE_ST_GL.M2_NG_HARD_G', 'ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.NG_EE_ST_GL', 'Thinks a g is heard at the end of ng.', '{"question":"In \"sing\", do you hear a g after the ng?","wrong_answer":"yes","correct_answer":"no"}'::jsonb, 'Kenyan English often adds g after ng, and spelling shows g.', 'Offer "yes" beside "no" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ng is one nose sound: sing, no g at the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.NG_EE_ST_GL.M2_EE_SHORT_I', 'ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.NG_EE_ST_GL', 'Hears the long e as the short i.', '{"question":"The teacher says \"sheep\". Sheep or ship?","wrong_answer":"ship","correct_answer":"sheep"}'::jsonb, 'Five-vowel home languages have one i.', 'Offer "ship" beside "sheep" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Long e is longer, lips in a smile: sheep.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.NG_EE_ST_GL.M2_ST_TWO_BEATS', 'ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.NG_EE_ST_GL', 'Hears a vowel between s and t.', '{"question":"Clap the beats in \"star\".","wrong_answer":"2 (si-tar)","correct_answer":"1"}'::jsonb, 'A vowel is slipped after s.', 'Offer "2 (si-tar)" beside "1" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ssss-t: one clap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.NG_EE_ST_GL.M2_GL_GR', 'ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.NG_EE_ST_GL', 'Hears gl as gr.', '{"question":"The teacher says \"glass\". Glass or grass?","wrong_answer":"grass","correct_answer":"glass"}'::jsonb, 'L and r merged.', 'Offer "grass" beside "glass" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tongue up: glass.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.SAY_VOWEL_SOUNDS.M2_SVS_SHIP_SHEEP', 'ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.SAY_VOWEL_SOUNDS', 'Says ship and sheep the same.', '{"question":"Say: ship, sheep","wrong_answer":"both as ship","correct_answer":"ship (short), sheep (long)"}'::jsonb, 'Five-vowel home languages.', 'Offer "both as ship" beside "ship (short), sheep (long)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sheep is longer, lips in a smile.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.SAY_VOWEL_SOUNDS.M2_SVS_CUP_CAP', 'ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.SAY_VOWEL_SOUNDS', 'Says cup as cap.', '{"question":"Say: a cup of tea","wrong_answer":"a cap of tea","correct_answer":"a cup of tea"}'::jsonb, 'One a sound for both.', 'Offer "a cap of tea" beside "a cup of tea" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Cup: short uh, mouth half open.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.SAY_VOWEL_SOUNDS.M2_SVS_BIRD', 'ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.SAY_VOWEL_SOUNDS', 'Says bird as bad or bed.', '{"question":"Say: The bird is on the branch.","wrong_answer":"The bad is on the branch.","correct_answer":"The bird is on the branch."}'::jsonb, 'The er sound is missing.', 'Offer "The bad is on the branch." beside "The bird is on the branch." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Relax the lips and hold it: bird.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.SAY_VOWEL_SOUNDS.M2_SVS_WEAK_FULL', 'ENGL.G2.LISTEN.T4_PRONUNCIATION_AND_VO.SAY_VOWEL_SOUNDS', 'Says a weak vowel in full.', '{"question":"Say: banana","wrong_answer":"ba-NA-NA with three full a sounds","correct_answer":"b(uh)-NA-n(uh)"}'::jsonb, 'Reading by letter: every vowel is given its full sound.', 'Offer "ba-NA-NA with three full a sounds" beside "b(uh)-NA-n(uh)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Only one part is strong; the others are quick uh.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T4_SIMPLE_PAST_TENSE.SIMPLE_PAST.M2_PA_GOED', 'ENGL.G2.LANGUA.T4_SIMPLE_PAST_TENSE.SIMPLE_PAST', 'Adds -ed to an irregular verb.', '{"question":"Yesterday we ... to Kisumu. (go)","wrong_answer":"goed","correct_answer":"went"}'::jsonb, 'The -ed rule is used for every verb.', 'Offer "goed" beside "went" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Some verbs change: go, went.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T4_SIMPLE_PAST_TENSE.SIMPLE_PAST.M2_PA_PRESENT', 'ENGL.G2.LANGUA.T4_SIMPLE_PAST_TENSE.SIMPLE_PAST', 'Uses the present for the past.', '{"question":"Last month I ... my grandmother. (visit)","wrong_answer":"visit","correct_answer":"visited"}'::jsonb, 'The time word is not linked to the verb.', 'Offer "visit" beside "visited" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Last month: add -ed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T4_SIMPLE_PAST_TENSE.SIMPLE_PAST.M2_PA_SPELL', 'ENGL.G2.LANGUA.T4_SIMPLE_PAST_TENSE.SIMPLE_PAST', 'Spells the -ed form wrongly.', '{"question":"Yesterday the bus ... at the gate. (stop)","wrong_answer":"stoped","correct_answer":"stopped"}'::jsonb, 'The doubling rule is not known.', 'Offer "stoped" beside "stopped" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Short vowel, one consonant: double it, stopped.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T4_SIMPLE_PAST_TENSE.SIMPLE_PAST.M2_PA_DID_PAST', 'ENGL.G2.LANGUA.T4_SIMPLE_PAST_TENSE.SIMPLE_PAST', 'Uses did with a past verb in a statement.', '{"question":"Yesterday I ... football. (play)","wrong_answer":"did played","correct_answer":"played"}'::jsonb, 'Did is added to show the past.', 'Offer "did played" beside "played" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'In a statement: just played.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T4_HANDWRITING.HANDWRITING_ASPECTS.M2_HA_NO_SPACE', 'ENGL.G2.WRITIN.T4_HANDWRITING.HANDWRITING_ASPECTS', 'Accepts writing with words run together.', '{"question":"Which writing is best?","wrong_answer":"Weplayedfootball.","correct_answer":"We played football."}'::jsonb, 'Speech has no gaps.', 'Offer "Weplayedfootball." beside "We played football." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A finger space between words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T4_HANDWRITING.HANDWRITING_ASPECTS.M2_HA_FLOAT', 'ENGL.G2.WRITIN.T4_HANDWRITING.HANDWRITING_ASPECTS', 'Accepts letters floating above the line.', '{"question":"Which writing is best?","wrong_answer":"letters above the line","correct_answer":"letters on the line"}'::jsonb, 'The line is not seen as the floor.', 'Offer "letters above the line" beside "letters on the line" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Every letter stands on the line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T4_HANDWRITING.HANDWRITING_ASPECTS.M2_HA_CAPS', 'ENGL.G2.WRITIN.T4_HANDWRITING.HANDWRITING_ASPECTS', 'Thinks capitals make writing better.', '{"question":"Which writing is best?","wrong_answer":"MY HOME IS NICE","correct_answer":"My home is nice."}'::jsonb, 'Capitals look neat and bold.', 'Offer "MY HOME IS NICE" beside "My home is nice." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Capitals only for starts and names.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T4_HANDWRITING.HANDWRITING_ASPECTS.M2_HA_DARK', 'ENGL.G2.WRITIN.T4_HANDWRITING.HANDWRITING_ASPECTS', 'Thinks dark, heavy writing is neat.', '{"question":"Which writing is neatest?","wrong_answer":"thick, dark, pressed letters","correct_answer":"light, even letters"}'::jsonb, 'Pressing hard is thought to be careful.', 'Offer "thick, dark, pressed letters" beside "light, even letters" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Light and even is neat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T4_HANDWRITING.GL_Y_WORDS.M2_GY_IE_FOR_Y', 'ENGL.G2.WRITIN.T4_HANDWRITING.GL_Y_WORDS', 'Writes ie or i for y at the end.', '{"question":"Fill: sunn_","wrong_answer":"sunni","correct_answer":"sunny"}'::jsonb, 'The ee sound is spelt as heard.', 'Offer "sunni" beside "sunny" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'At the end of a long word, ee is often y.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T4_HANDWRITING.GL_Y_WORDS.M2_GY_GR_FOR_GL', 'ENGL.G2.WRITIN.T4_HANDWRITING.GL_Y_WORDS', 'Writes gr for gl.', '{"question":"Make the word: _ad (happy)","wrong_answer":"grad","correct_answer":"glad"}'::jsonb, 'L and r merged.', 'Offer "grad" beside "glad" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Glad: g-l.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T4_HANDWRITING.GL_Y_WORDS.M2_GY_EXTRA_VOWEL', 'ENGL.G2.WRITIN.T4_HANDWRITING.GL_Y_WORDS', 'Writes a vowel between g and l.', '{"question":"Choose: gulue, glue","wrong_answer":"gulue","correct_answer":"glue"}'::jsonb, 'The word is spelt as said with a slipped-in vowel.', 'Offer "gulue" beside "glue" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'G and l sit together: gl.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T4_HANDWRITING.GL_Y_WORDS.M2_GY_JULY', 'ENGL.G2.WRITIN.T4_HANDWRITING.GL_Y_WORDS', 'Spells July as Julai or Jully.', '{"question":"Choose the month: Julai, July, Jully","wrong_answer":"Julai","correct_answer":"July"}'::jsonb, 'Kiswahili Julai is carried over.', 'Offer "Julai" beside "July" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'July: J-u-l-y.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T5_PRONUNCIATION_AND_VO.NT_SL_AR_ND_NK.M2_AR_SHORT_A', 'ENGL.G2.LISTEN.T5_PRONUNCIATION_AND_VO.NT_SL_AR_ND_NK', 'Hears ar (car) as the short a of cat.', '{"question":"Which word has the same vowel as \"car\": cat, star, cap?","wrong_answer":"cat","correct_answer":"star"}'::jsonb, 'The child hears a and does not know ar as one long sound.', 'Offer "cat" beside "star" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ar is long and open: car, star, market.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T5_PRONUNCIATION_AND_VO.NT_SL_AR_ND_NK.M2_NT_ND', 'ENGL.G2.LISTEN.T5_PRONUNCIATION_AND_VO.NT_SL_AR_ND_NK', 'Hears nt as nd.', '{"question":"The teacher says \"bent\". Bent or bend?","wrong_answer":"bend","correct_answer":"bent"}'::jsonb, 'T and d at the end are swapped.', 'Offer "bend" beside "bent" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Bent ends with a puff.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T5_PRONUNCIATION_AND_VO.NT_SL_AR_ND_NK.M2_NK_NG', 'ENGL.G2.LISTEN.T5_PRONUNCIATION_AND_VO.NT_SL_AR_ND_NK', 'Hears nk as ng.', '{"question":"The teacher says \"sink\". Sink or sing?","wrong_answer":"sing","correct_answer":"sink"}'::jsonb, 'The k after n is missed.', 'Offer "sing" beside "sink" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sink ends with a click.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T5_PRONUNCIATION_AND_VO.NT_SL_AR_ND_NK.M2_SL_S', 'ENGL.G2.LISTEN.T5_PRONUNCIATION_AND_VO.NT_SL_AR_ND_NK', 'Does not hear the l in sl.', '{"question":"The teacher says \"slip\". Slip or sip?","wrong_answer":"sip","correct_answer":"slip"}'::jsonb, 'The second consonant of the cluster is lost.', 'Offer "sip" beside "slip" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'S-lll-ip.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T5_NOUNS_PLURALS_OF_IRR.IRREGULAR_PLURALS.M2_PL_CHILDS', 'ENGL.G2.WRITIN.T5_NOUNS_PLURALS_OF_IRR.IRREGULAR_PLURALS', 'Adds -s to an irregular noun.', '{"question":"One child, two ...","wrong_answer":"childs","correct_answer":"children"}'::jsonb, 'The -s rule for every noun.', 'Offer "childs" beside "children" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Child, children.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T5_NOUNS_PLURALS_OF_IRR.IRREGULAR_PLURALS.M2_PL_FEETS', 'ENGL.G2.WRITIN.T5_NOUNS_PLURALS_OF_IRR.IRREGULAR_PLURALS', 'Adds -s to an irregular plural.', '{"question":"Wash your ... (foot)","wrong_answer":"feets","correct_answer":"feet"}'::jsonb, 'Feet is known and -s added to be sure.', 'Offer "feets" beside "feet" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Feet is already plural.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T5_NOUNS_PLURALS_OF_IRR.IRREGULAR_PLURALS.M2_PL_SHEEPS', 'ENGL.G2.WRITIN.T5_NOUNS_PLURALS_OF_IRR.IRREGULAR_PLURALS', 'Adds -s to sheep.', '{"question":"The shopkeeper sold three ...","wrong_answer":"sheeps","correct_answer":"sheep"}'::jsonb, 'The -s rule.', 'Offer "sheeps" beside "sheep" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One sheep, three sheep.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T5_NOUNS_PLURALS_OF_IRR.IRREGULAR_PLURALS.M2_PL_ONE_TEETH', 'ENGL.G2.WRITIN.T5_NOUNS_PLURALS_OF_IRR.IRREGULAR_PLURALS', 'Uses the plural for one.', '{"question":"I lost one ...","wrong_answer":"teeth","correct_answer":"tooth"}'::jsonb, 'Teeth is heard more often.', 'Offer "teeth" beside "tooth" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One tooth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T5_SPELLING.SPELL_GRADE_WORDS.M2_SG_SOUND', 'ENGL.G2.WRITIN.T5_SPELLING.SPELL_GRADE_WORDS', 'Spells a word as it is said.', '{"question":"Choose: mani, money, mony","wrong_answer":"mani","correct_answer":"money"}'::jsonb, 'Spelling by sound alone.', 'Offer "mani" beside "money" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look, cover, write, check.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T5_SPELLING.SPELL_GRADE_WORDS.M2_SG_DROP_LETTER', 'ENGL.G2.WRITIN.T5_SPELLING.SPELL_GRADE_WORDS', 'Leaves out a letter.', '{"question":"Choose: garden, gardn, gaden","wrong_answer":"gaden","correct_answer":"garden"}'::jsonb, 'The r is not heard in garden.', 'Offer "gaden" beside "garden" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say every part: gar-den.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T5_SPELLING.SPELL_GRADE_WORDS.M2_SG_SWAP', 'ENGL.G2.WRITIN.T5_SPELLING.SPELL_GRADE_WORDS', 'Swaps two letters.', '{"question":"Choose: siad, said","wrong_answer":"siad","correct_answer":"said"}'::jsonb, 'The letters are remembered but not their order.', 'Offer "siad" beside "said" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Said: s-a-i-d.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T5_SPELLING.SPELL_GRADE_WORDS.M2_SG_DOUBLE', 'ENGL.G2.WRITIN.T5_SPELLING.SPELL_GRADE_WORDS', 'Doubles letters that should be single, or the reverse.', '{"question":"Choose: shopp, shop","wrong_answer":"shopp","correct_answer":"shop"}'::jsonb, 'The child is unsure when letters double.', 'Offer "shopp" beside "shop" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Shop ends with one p.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T6_PRONUNCIATION_AND_VO.EAR_TH_WH_TW.M2_TH_T', 'ENGL.G2.LISTEN.T6_PRONUNCIATION_AND_VO.EAR_TH_WH_TW', 'Hears th (thin) as t.', '{"question":"The teacher says \"thin\". Thin or tin?","wrong_answer":"tin","correct_answer":"thin"}'::jsonb, 'Th is missing in most Kenyan home languages.', 'Offer "tin" beside "thin" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tongue between the teeth, blow: thin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T6_PRONUNCIATION_AND_VO.EAR_TH_WH_TW.M2_THV_D', 'ENGL.G2.LISTEN.T6_PRONUNCIATION_AND_VO.EAR_TH_WH_TW', 'Hears th (this) as d.', '{"question":"The teacher says \"they\". They or day?","wrong_answer":"day","correct_answer":"they"}'::jsonb, 'The voiced th is heard as the nearest sound, d.', 'Offer "day" beside "they" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tongue between the teeth with a buzz: they.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T6_PRONUNCIATION_AND_VO.EAR_TH_WH_TW.M2_WH_H', 'ENGL.G2.LISTEN.T6_PRONUNCIATION_AND_VO.EAR_TH_WH_TW', 'Thinks wh says h.', '{"question":"Which word starts with the same sound as \"wet\": wheel, heel, feel?","wrong_answer":"heel","correct_answer":"wheel"}'::jsonb, 'The child sounds the h in wh.', 'Offer "heel" beside "wheel" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'In wheel, white and when, wh says w.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T6_PRONUNCIATION_AND_VO.EAR_TH_WH_TW.M2_EAR_TWO_BEATS', 'ENGL.G2.LISTEN.T6_PRONUNCIATION_AND_VO.EAR_TH_WH_TW', 'Hears ear as two beats (i-a).', '{"question":"Clap the beats in \"deer\".","wrong_answer":"2 (di-a)","correct_answer":"1"}'::jsonb, 'Each vowel letter is given its own beat.', 'Offer "2 (di-a)" beside "1" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ear glides in one beat: deer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T6_TENSE_PAST_CONTINUOU.PAST_CONTINUOUS.M2_PC_IS_ING', 'ENGL.G2.LANGUA.T6_TENSE_PAST_CONTINUOU.PAST_CONTINUOUS', 'Uses is or are for the past continuous.', '{"question":"Yesterday at four she ... cooking.","wrong_answer":"is","correct_answer":"was"}'::jsonb, 'The present continuous is the first learnt.', 'Offer "is" beside "was" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Yesterday: was cooking.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T6_TENSE_PAST_CONTINUOU.PAST_CONTINUOUS.M2_PC_NO_BE', 'ENGL.G2.LANGUA.T6_TENSE_PAST_CONTINUOU.PAST_CONTINUOUS', 'Leaves out was or were.', '{"question":"We ... digging when it rained.","wrong_answer":"(nothing): We digging","correct_answer":"were"}'::jsonb, 'The small word is not heard.', 'Offer "(nothing): We digging" beside "were" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Was or were before -ing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T6_TENSE_PAST_CONTINUOU.PAST_CONTINUOUS.M2_PC_THEY_WAS', 'ENGL.G2.LANGUA.T6_TENSE_PAST_CONTINUOU.PAST_CONTINUOUS', 'Uses was with they or we.', '{"question":"They ... watering the plants.","wrong_answer":"was","correct_answer":"were"}'::jsonb, 'Was for every past.', 'Offer "was" beside "were" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'They: were.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T6_TENSE_PAST_CONTINUOU.PAST_CONTINUOUS.M2_PC_ING_SPELL', 'ENGL.G2.LANGUA.T6_TENSE_PAST_CONTINUOU.PAST_CONTINUOUS', 'Spells the -ing form wrongly.', '{"question":"He was ... to school. (run)","wrong_answer":"runing","correct_answer":"running"}'::jsonb, 'The doubling rule is not known.', 'Offer "runing" beside "running" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Run, running: double the n.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T6_SPELLING.SPELL_TH_WH_TW_EAR.M2_SWT_TH_T', 'ENGL.G2.WRITIN.T6_SPELLING.SPELL_TH_WH_TW_EAR', 'Writes t or d for th.', '{"question":"Choose: torn, thorn (on a rose)","wrong_answer":"torn","correct_answer":"thorn"}'::jsonb, 'Th is said as t and spelt as said.', 'Offer "torn" beside "thorn" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Thorn: t-h.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T6_SPELLING.SPELL_TH_WH_TW_EAR.M2_SWT_WH_W', 'ENGL.G2.WRITIN.T6_SPELLING.SPELL_TH_WH_TW_EAR', 'Writes w for wh.', '{"question":"Choose: weel, wheel","wrong_answer":"weel","correct_answer":"wheel"}'::jsonb, 'The h is silent and left out.', 'Offer "weel" beside "wheel" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Wheel has a silent h: w-h.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T6_SPELLING.SPELL_TH_WH_TW_EAR.M2_SWT_TW_TU', 'ENGL.G2.WRITIN.T6_SPELLING.SPELL_TH_WH_TW_EAR', 'Writes tu for tw.', '{"question":"Choose: tuig, twig","wrong_answer":"tuig","correct_answer":"twig"}'::jsonb, 'W is heard as u.', 'Offer "tuig" beside "twig" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tw: t then w.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T6_SPELLING.SPELL_TH_WH_TW_EAR.M2_SWT_EAR_IA', 'ENGL.G2.WRITIN.T6_SPELLING.SPELL_TH_WH_TW_EAR', 'Writes ia for ear.', '{"question":"Choose: nia, near","wrong_answer":"nia","correct_answer":"near"}'::jsonb, 'The ear sound is spelt as heard.', 'Offer "nia" beside "near" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The sound eer is often spelt ear.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T7_PRONUNCIATION_AND_VO.ND_NK_AY_OA_IE.M2_IE_SHORT_I', 'ENGL.G2.LISTEN.T7_PRONUNCIATION_AND_VO.ND_NK_AY_OA_IE', 'Hears the long i (bike) as short i (bit).', '{"question":"The teacher says \"kite\". Kite or kit?","wrong_answer":"kit","correct_answer":"kite"}'::jsonb, 'The vowel slide of long i is not heard.', 'Offer "kit" beside "kite" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Long i slides: a-ee, kite.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T7_PRONUNCIATION_AND_VO.ND_NK_AY_OA_IE.M2_OE_SHORT_O', 'ENGL.G2.LISTEN.T7_PRONUNCIATION_AND_VO.ND_NK_AY_OA_IE', 'Hears the long o (nose) as short o.', '{"question":"The teacher says \"hope\". Hope or hop?","wrong_answer":"hop","correct_answer":"hope"}'::jsonb, 'One o sound in the home language.', 'Offer "hop" beside "hope" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Long o slides: o-oo, hope.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T7_PRONUNCIATION_AND_VO.ND_NK_AY_OA_IE.M2_ND_DROP', 'ENGL.G2.LISTEN.T7_PRONUNCIATION_AND_VO.ND_NK_AY_OA_IE', 'Does not hear the d in nd.', '{"question":"The teacher says \"band\". Band or ban?","wrong_answer":"ban","correct_answer":"band"}'::jsonb, 'The last consonant is lost.', 'Offer "ban" beside "band" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ban-d: listen for d.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T7_PRONUNCIATION_AND_VO.ND_NK_AY_OA_IE.M2_AY_SHORT_A', 'ENGL.G2.LISTEN.T7_PRONUNCIATION_AND_VO.ND_NK_AY_OA_IE', 'Hears the long a (cake) as the short a (cat).', '{"question":"The teacher says \"pain\". Pain or pan?","wrong_answer":"pan","correct_answer":"pain"}'::jsonb, 'The home language has one a sound.', 'Offer "pan" beside "pain" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Long a slides: e-ee, pain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T7_COMPREHENSION.CHARACTERS_EVENTS.M2_CE_ANIMALS', 'ENGL.G2.READIN.T7_COMPREHENSION.CHARACTERS_EVENTS', 'Thinks animals cannot be characters.', '{"question":"Hare and Tortoise had a race. Who are the characters?","wrong_answer":"none, they are animals","correct_answer":"Hare and Tortoise"}'::jsonb, 'Characters are thought of as people.', 'Offer "none, they are animals" beside "Hare and Tortoise" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Anyone who acts or talks is a character.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T7_COMPREHENSION.CHARACTERS_EVENTS.M2_CE_MAIN_ONLY', 'ENGL.G2.READIN.T7_COMPREHENSION.CHARACTERS_EVENTS', 'Names only one character.', '{"question":"Mama and Baba took Ali to the clinic. Who is in the story?","wrong_answer":"Ali","correct_answer":"Mama, Baba and Ali"}'::jsonb, 'The child stops at one name.', 'Offer "Ali" beside "Mama, Baba and Ali" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'List everyone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T7_COMPREHENSION.CHARACTERS_EVENTS.M2_CE_LOOKS_ONLY', 'ENGL.G2.READIN.T7_COMPREHENSION.CHARACTERS_EVENTS', 'Describes only how a character looks, not what he or she is like.', '{"question":"Juma shared his lunch with a new boy. What is Juma like?","wrong_answer":"tall","correct_answer":"kind"}'::jsonb, 'Describing is taken as describing looks.', 'Offer "tall" beside "kind" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'What does what he did tell us?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T7_COMPREHENSION.CHARACTERS_EVENTS.M2_CE_EVENT_PERSON', 'ENGL.G2.READIN.T7_COMPREHENSION.CHARACTERS_EVENTS', 'Gives a person when asked what happened.', '{"question":"What happened in the story of the broken cup?","wrong_answer":"Achieng","correct_answer":"Achieng broke a cup and said sorry."}'::jsonb, 'Who and what are mixed.', 'Offer "Achieng" beside "Achieng broke a cup and said sorry." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'What happened is an action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T7_CONJUNCTIONS.CONJ_OR.M2_OR_AND', 'ENGL.G2.LANGUA.T7_CONJUNCTIONS.CONJ_OR', 'Uses and when giving a choice.', '{"question":"Do you want tea ... milk? (one of them)","wrong_answer":"and","correct_answer":"or"}'::jsonb, 'And is the joining word used most.', 'Offer "and" beside "or" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One of two: or.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T7_CONJUNCTIONS.CONJ_OR.M2_OR_YES', 'ENGL.G2.LANGUA.T7_CONJUNCTIONS.CONJ_OR', 'Answers an or question with yes.', '{"question":"Do you go by bus or on foot?","wrong_answer":"Yes.","correct_answer":"I go on foot."}'::jsonb, 'Every question is treated as yes or no.', 'Offer "Yes." beside "I go on foot." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Choose one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T7_CONJUNCTIONS.CONJ_OR.M2_OR_BOTH', 'ENGL.G2.LANGUA.T7_CONJUNCTIONS.CONJ_OR', 'Chooses both when asked to choose one.', '{"question":"Would you like a mango or a banana?","wrong_answer":"a mango and a banana","correct_answer":"a mango (or a banana)"}'::jsonb, 'The word or is not heard as one of two.', 'Offer "a mango and a banana" beside "a mango (or a banana)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Or: pick one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T7_CONJUNCTIONS.CONJ_OR.M2_OR_POSITION', 'ENGL.G2.LANGUA.T7_CONJUNCTIONS.CONJ_OR', 'Puts or in the wrong place.', '{"question":"Join: Is it Monday? Is it Tuesday?","wrong_answer":"Or is it Monday Tuesday?","correct_answer":"Is it Monday or Tuesday?"}'::jsonb, 'The child adds or at the start like a question word.', 'Offer "Or is it Monday Tuesday?" beside "Is it Monday or Tuesday?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Or goes between the two choices.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T7_SPELLING.SPELL_NK_ND_AR.M2_SNA_NK_NG', 'ENGL.G2.WRITIN.T7_SPELLING.SPELL_NK_ND_AR', 'Writes ng for nk.', '{"question":"Choose: ping, pink","wrong_answer":"ping","correct_answer":"pink"}'::jsonb, 'Nk is heard as ng.', 'Offer "ping" beside "pink" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Pink ends with k.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T7_SPELLING.SPELL_NK_ND_AR.M2_SNA_ND_N', 'ENGL.G2.WRITIN.T7_SPELLING.SPELL_NK_ND_AR', 'Leaves out the d in nd.', '{"question":"Choose: han, hand","wrong_answer":"han","correct_answer":"hand"}'::jsonb, 'The final d is not heard.', 'Offer "han" beside "hand" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Hand ends with d.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T7_SPELLING.SPELL_NK_ND_AR.M2_SNA_AR_A', 'ENGL.G2.WRITIN.T7_SPELLING.SPELL_NK_ND_AR', 'Writes a for ar.', '{"question":"Choose: ca, car","wrong_answer":"ca","correct_answer":"car"}'::jsonb, 'The r is silent in British English and is left out.', 'Offer "ca" beside "car" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Car: c-a-r.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T7_SPELLING.SPELL_NK_ND_AR.M2_SNA_AR_AA', 'ENGL.G2.WRITIN.T7_SPELLING.SPELL_NK_ND_AR', 'Writes aa for ar.', '{"question":"Choose: paak, park","wrong_answer":"paak","correct_answer":"park"}'::jsonb, 'The long a is spelt with two a letters, as in some Kenyan languages.', 'Offer "paak" beside "park" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Long a in park is spelt ar.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T8_PRONUNCIATION_AND_VO.BR_SCHWA_EE_AY_OA.M2_SCHWA_FULL', 'ENGL.G2.LISTEN.T8_PRONUNCIATION_AND_VO.BR_SCHWA_EE_AY_OA', 'Expects the weak vowel to sound like its letter.', '{"question":"In \"teacher\", which part is weak and quick?","wrong_answer":"teach","correct_answer":"er"}'::jsonb, 'Reading by letter: every vowel is given its full sound.', 'Offer "teach" beside "er" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The end of teacher is a quick uh.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T8_PRONUNCIATION_AND_VO.BR_SCHWA_EE_AY_OA.M2_BR_BL', 'ENGL.G2.LISTEN.T8_PRONUNCIATION_AND_VO.BR_SCHWA_EE_AY_OA', 'Hears br as bl.', '{"question":"The teacher says \"brush\". Brush or blush?","wrong_answer":"blush","correct_answer":"brush"}'::jsonb, 'L and r merged.', 'Offer "blush" beside "brush" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Curl the tongue: brush.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T8_PRONUNCIATION_AND_VO.BR_SCHWA_EE_AY_OA.M2_EE_EA_DIFFERENT', 'ENGL.G2.LISTEN.T8_PRONUNCIATION_AND_VO.BR_SCHWA_EE_AY_OA', 'Thinks ee and ea must sound different.', '{"question":"Do \"seat\" and \"feet\" have the same vowel sound?","wrong_answer":"no","correct_answer":"yes"}'::jsonb, 'Different letters are expected to mean different sounds.', 'Offer "no" beside "yes" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ee and ea both say the long e.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T8_PRONUNCIATION_AND_VO.BR_SCHWA_EE_AY_OA.M2_OA_OW_DIFFERENT', 'ENGL.G2.LISTEN.T8_PRONUNCIATION_AND_VO.BR_SCHWA_EE_AY_OA', 'Thinks oa and ow (snow) must sound different.', '{"question":"Do \"boat\" and \"snow\" have the same vowel sound?","wrong_answer":"no","correct_answer":"yes"}'::jsonb, 'Different letters are expected to mean different sounds.', 'Offer "no" beside "yes" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Oa and ow in snow both say the long o.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.CARDINAL_ORDINAL.M2_CO_ONETH', 'ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.CARDINAL_ORDINAL', 'Makes order words by adding -th to every number.', '{"question":"Akinyi was the ... in the race. (1)","wrong_answer":"oneth","correct_answer":"first"}'::jsonb, 'The -th rule (fourth, sixth) is used for all.', 'Offer "oneth" beside "first" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'First, second, third are special.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.CARDINAL_ORDINAL.M2_CO_FIVETH', 'ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.CARDINAL_ORDINAL', 'Writes fiveth for fifth.', '{"question":"May is the ... month. (5)","wrong_answer":"fiveth","correct_answer":"fifth"}'::jsonb, 'The number word is kept whole.', 'Offer "fiveth" beside "fifth" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Five, fifth: ve becomes f.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.CARDINAL_ORDINAL.M2_CO_POSITION_TWO', 'ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.CARDINAL_ORDINAL', 'Uses a counting number for a position.', '{"question":"I came ... in the race.","wrong_answer":"number two","correct_answer":"second"}'::jsonb, 'Kenyan school talk (position two) is carried in.', 'Offer "number two" beside "second" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'For a place in a line or race: second.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.CARDINAL_ORDINAL.M2_CO_ORDINAL_COUNT', 'ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.CARDINAL_ORDINAL', 'Uses an order word when counting.', '{"question":"I have ... pencils. (2)","wrong_answer":"second","correct_answer":"two"}'::jsonb, 'The two kinds of number word are mixed.', 'Offer "second" beside "two" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'How many: two. Which place: second.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.THESE_THOSE.M2_TT_THIS_PLURAL', 'ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.THESE_THOSE', 'Uses this with a plural noun.', '{"question":"... books on my desk are new.","wrong_answer":"This","correct_answer":"These"}'::jsonb, 'This is learnt first.', 'Offer "This" beside "These" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'More than one near: these.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.THESE_THOSE.M2_TT_NEAR_FAR', 'ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.THESE_THOSE', 'Uses these for things far away.', '{"question":"Look at ... birds on the far tree.","wrong_answer":"these","correct_answer":"those"}'::jsonb, 'Near and far are not linked to the words.', 'Offer "these" beside "those" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Far: those.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.THESE_THOSE.M2_TT_SINGULAR_NOUN', 'ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.THESE_THOSE', 'Uses a singular noun after these or those.', '{"question":"Those ... are tall. (tree)","wrong_answer":"tree","correct_answer":"trees"}'::jsonb, 'The noun is not made plural.', 'Offer "tree" beside "trees" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Those trees: more than one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.THESE_THOSE.M2_TT_THEM', 'ENGL.G2.LANGUA.T8_CARDINAL_AND_ORDINAL.THESE_THOSE', 'Uses them for those.', '{"question":"Pass me ... cups.","wrong_answer":"them","correct_answer":"those"}'::jsonb, 'Common in spoken English.', 'Offer "them" beside "those" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Those cups.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T8_SPELLING.SPELL_VOWEL_TEAMS.M2_SVT_ONE_LETTER', 'ENGL.G2.WRITIN.T8_SPELLING.SPELL_VOWEL_TEAMS', 'Writes a long vowel with one letter.', '{"question":"Choose: red, read (a book)","wrong_answer":"red","correct_answer":"read"}'::jsonb, 'Each sound is given one letter.', 'Offer "red" beside "read" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Long e here is ea: read.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T8_SPELLING.SPELL_VOWEL_TEAMS.M2_SVT_BR_BL', 'ENGL.G2.WRITIN.T8_SPELLING.SPELL_VOWEL_TEAMS', 'Writes bl for br.', '{"question":"Choose: blush, brush (for teeth)","wrong_answer":"blush","correct_answer":"brush"}'::jsonb, 'L and r merged.', 'Offer "blush" beside "brush" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Brush: b-r.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T8_SPELLING.SPELL_VOWEL_TEAMS.M2_SVT_ER_A', 'ENGL.G2.WRITIN.T8_SPELLING.SPELL_VOWEL_TEAMS', 'Writes a for the weak er at the end.', '{"question":"Choose: ticha, teacher","wrong_answer":"ticha","correct_answer":"teacher"}'::jsonb, 'Kiswahili ticha is carried over and the weak end is spelt as heard.', 'Offer "ticha" beside "teacher" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Teacher ends with er.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T8_SPELLING.SPELL_VOWEL_TEAMS.M2_SVT_OA_O', 'ENGL.G2.WRITIN.T8_SPELLING.SPELL_VOWEL_TEAMS', 'Writes o for oa.', '{"question":"Choose: bord, board","wrong_answer":"bord","correct_answer":"board"}'::jsonb, 'The long o is spelt with one letter.', 'Offer "bord" beside "board" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Board: oa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T9_PRONUNCIATION_AND_VO.CR_ER_Y_AR.M2_ER_A', 'ENGL.G2.LISTEN.T9_PRONUNCIATION_AND_VO.CR_ER_Y_AR', 'Hears er (bird, her) as a.', '{"question":"Which word has the same vowel as \"bird\": bad, her, bed?","wrong_answer":"bad","correct_answer":"her"}'::jsonb, 'The /ɜː/ sound is missing in Kenyan home languages.', 'Offer "bad" beside "her" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Er, ir and ur say the same long sound: her, bird, turn.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T9_PRONUNCIATION_AND_VO.CR_ER_Y_AR.M2_Y_LONG_I', 'ENGL.G2.LISTEN.T9_PRONUNCIATION_AND_VO.CR_ER_Y_AR', 'Hears y at the end of happy as the y of sky.', '{"question":"Which word ends with the same sound as \"puppy\": sky, funny, cry?","wrong_answer":"sky","correct_answer":"funny"}'::jsonb, 'Y is learnt as the i of my.', 'Offer "sky" beside "funny" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'At the end of a long word y says ee: puppy, funny.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T9_PRONUNCIATION_AND_VO.CR_ER_Y_AR.M2_Y_CONSONANT', 'ENGL.G2.LISTEN.T9_PRONUNCIATION_AND_VO.CR_ER_Y_AR', 'Expects y at the end to say the y of yes.', '{"question":"Does \"happy\" end with the sound in \"yes\"?","wrong_answer":"yes","correct_answer":"no, it ends with ee"}'::jsonb, 'Y is first learnt as a consonant.', 'Offer "yes" beside "no, it ends with ee" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'At the end y is a vowel: ee.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T9_PRONUNCIATION_AND_VO.CR_ER_Y_AR.M2_CR_CL', 'ENGL.G2.LISTEN.T9_PRONUNCIATION_AND_VO.CR_ER_Y_AR', 'Hears cr as cl.', '{"question":"The teacher says \"crash\". Crash or clash?","wrong_answer":"clash","correct_answer":"crash"}'::jsonb, 'L and r merged.', 'Offer "clash" beside "crash" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Curl the tongue: crash.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T9_COMPREHENSION.SETTING.M2_SE_PERSON', 'ENGL.G2.READIN.T9_COMPREHENSION.SETTING', 'Gives a person for the setting.', '{"question":"Grandma sat under the tree in the evening. Where is the story?","wrong_answer":"Grandma","correct_answer":"under the tree"}'::jsonb, 'Setting is a new word.', 'Offer "Grandma" beside "under the tree" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Setting is where and when.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T9_COMPREHENSION.SETTING.M2_SE_NO_TIME', 'ENGL.G2.READIN.T9_COMPREHENSION.SETTING', 'Gives the place but not the time.', '{"question":"On a rainy night, the family sat in the kitchen. When and where?","wrong_answer":"in the kitchen","correct_answer":"in the kitchen on a rainy night"}'::jsonb, 'Setting is taught as a place.', 'Offer "in the kitchen" beside "in the kitchen on a rainy night" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Where and when.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T9_COMPREHENSION.SETTING.M2_SE_OWN_PLACE', 'ENGL.G2.READIN.T9_COMPREHENSION.SETTING', 'Gives his or her own home as the setting.', '{"question":"The story happens at a lake. Where does it happen?","wrong_answer":"at my home","correct_answer":"at a lake"}'::jsonb, 'Own life is mixed in.', 'Offer "at my home" beside "at a lake" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Where in the story?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T9_COMPREHENSION.SETTING.M2_SE_PICTURE_WRONG', 'ENGL.G2.READIN.T9_COMPREHENSION.SETTING', 'Chooses a picture with the wrong time of day.', '{"question":"Text: In the morning the sun came up over the farm. Which picture?","wrong_answer":"a farm at night with the moon","correct_answer":"a farm in the morning sun"}'::jsonb, 'The time word is skipped.', 'Offer "a farm at night with the moon" beside "a farm in the morning sun" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Morning means sun coming up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T9_COMPREHENSION.MAIN_IDEA.M2_MI_DETAIL', 'ENGL.G2.READIN.T9_COMPREHENSION.MAIN_IDEA', 'Chooses a detail as the main idea.', '{"question":"A text about how children help at home: they sweep, cook and fetch water. What is it about?","wrong_answer":"fetching water","correct_answer":"how children help at home"}'::jsonb, 'One detail stands out.', 'Offer "fetching water" beside "how children help at home" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Which answer covers all of it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T9_COMPREHENSION.MAIN_IDEA.M2_MI_TOO_WIDE', 'ENGL.G2.READIN.T9_COMPREHENSION.MAIN_IDEA', 'Chooses an idea that is too wide.', '{"question":"A text about caring for a goat. What is it about?","wrong_answer":"animals","correct_answer":"caring for a goat"}'::jsonb, 'A true word that is too wide.', 'Offer "animals" beside "caring for a goat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Is the whole text about all animals?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T9_COMPREHENSION.MAIN_IDEA.M2_MI_FIRST', 'ENGL.G2.READIN.T9_COMPREHENSION.MAIN_IDEA', 'Takes the first sentence as the main idea.', '{"question":"Text starts: \"It was Saturday.\" It is about planting beans. Main idea?","wrong_answer":"It was Saturday.","correct_answer":"planting beans"}'::jsonb, 'The first sentence is trusted.', 'Offer "It was Saturday." beside "planting beans" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read it all first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T9_COMPREHENSION.MAIN_IDEA.M2_MI_STORY_ONLY', 'ENGL.G2.READIN.T9_COMPREHENSION.MAIN_IDEA', 'Thinks every text is a story.', '{"question":"A text tells the months of the year in order. Why was it written?","wrong_answer":"to tell a story","correct_answer":"to give facts about the months"}'::jsonb, 'Most texts read have been stories.', 'Offer "to tell a story" beside "to give facts about the months" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Characters, or facts?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T9_COMPREHENSION.RETELL_IN_ORDER.M2_RO_ORDER', 'ENGL.G2.READIN.T9_COMPREHENSION.RETELL_IN_ORDER', 'Tells the events out of order.', '{"question":"Retell: Ali woke up, washed, ate and went to school.","wrong_answer":"Ali went to school. He woke up.","correct_answer":"First Ali woke up. Then he washed. Next he ate. Last he went to school."}'::jsonb, 'Events are told as remembered.', 'Offer "Ali went to school. He woke up." beside "First Ali woke up. Then he washed. Next he ate. Last he went to school." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'First, next, then, last.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T9_COMPREHENSION.RETELL_IN_ORDER.M2_RO_READS', 'ENGL.G2.READIN.T9_COMPREHENSION.RETELL_IN_ORDER', 'Reads the text again instead of retelling.', '{"question":"Tell me what happened.","wrong_answer":"reads the page aloud","correct_answer":"tells it in own words"}'::jsonb, 'Retelling is taken as repeating.', 'Offer "reads the page aloud" beside "tells it in own words" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Close the book and tell it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T9_COMPREHENSION.RETELL_IN_ORDER.M2_RO_NO_NAMES', 'ENGL.G2.READIN.T9_COMPREHENSION.RETELL_IN_ORDER', 'Uses he and she without names.', '{"question":"Retell the story of Tom and Mary.","wrong_answer":"He went and she said.","correct_answer":"Tom went to the shop. Mary said ..."}'::jsonb, 'The listener is forgotten.', 'Offer "He went and she said." beside "Tom went to the shop. Mary said ..." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say the name first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T9_COMPREHENSION.RETELL_IN_ORDER.M2_RO_ONE_EVENT', 'ENGL.G2.READIN.T9_COMPREHENSION.RETELL_IN_ORDER', 'Tells one event and stops.', '{"question":"What happened in the story?","wrong_answer":"The goat ran away.","correct_answer":"The goat ran away. Akinyi looked for it. She found it by the river."}'::jsonb, 'The child does not know how much to tell.', 'Offer "The goat ran away." beside "The goat ran away. Akinyi looked for it. She found it by the river." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'What happened next?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T9_WORD_SETS_GENDER_SET.GENDER_PAIRS.M2_GP_SWAP', 'ENGL.G2.LANGUA.T9_WORD_SETS_GENDER_SET.GENDER_PAIRS', 'Gives the male for the female.', '{"question":"A female chicken is a ...","wrong_answer":"cock","correct_answer":"hen"}'::jsonb, 'The pair is learnt together.', 'Offer "cock" beside "hen" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Hen is the mother; cock crows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T9_WORD_SETS_GENDER_SET.GENDER_PAIRS.M2_GP_BOY_COW', 'ENGL.G2.LANGUA.T9_WORD_SETS_GENDER_SET.GENDER_PAIRS', 'Makes a male by adding boy or man.', '{"question":"A male cow is a ...","wrong_answer":"boy cow","correct_answer":"bull"}'::jsonb, 'Kiswahili adds a word (ng''ombe dume), so the child adds one.', 'Offer "boy cow" beside "bull" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'English has its own word: bull.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T9_WORD_SETS_GENDER_SET.GENDER_PAIRS.M2_GP_SAME_WORD', 'ENGL.G2.LANGUA.T9_WORD_SETS_GENDER_SET.GENDER_PAIRS', 'Uses the same word for both.', '{"question":"A female lion is a ...","wrong_answer":"lion","correct_answer":"lioness"}'::jsonb, 'The female word is not known.', 'Offer "lion" beside "lioness" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Lion and lioness.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T9_WORD_SETS_GENDER_SET.GENDER_PAIRS.M2_GP_UNCLE_AUNT', 'ENGL.G2.LANGUA.T9_WORD_SETS_GENDER_SET.GENDER_PAIRS', 'Swaps uncle and aunt.', '{"question":"My father''s sister is my ...","wrong_answer":"uncle","correct_answer":"aunt"}'::jsonb, 'The side of the family is thought of, not man or woman.', 'Offer "uncle" beside "aunt" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Aunt is a woman.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T9_PUNCTUATION_THE_COMM.COMMA_LIST.M2_LC_NONE', 'ENGL.G2.WRITIN.T9_PUNCTUATION_THE_COMM.COMMA_LIST', 'Leaves out commas in a list.', '{"question":"Punctuate: We keep cows goats hens and ducks.","wrong_answer":"We keep cows goats hens and ducks.","correct_answer":"We keep cows, goats, hens and ducks."}'::jsonb, 'Where commas go is not heard.', 'Offer "We keep cows goats hens and ducks." beside "We keep cows, goats, hens and ducks." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A comma between each item.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T9_PUNCTUATION_THE_COMM.COMMA_LIST.M2_LC_AND_EVERY', 'ENGL.G2.WRITIN.T9_PUNCTUATION_THE_COMM.COMMA_LIST', 'Joins every item with and.', '{"question":"Write the list: cows, goats, hens.","wrong_answer":"cows and goats and hens","correct_answer":"cows, goats and hens"}'::jsonb, 'And is repeated in speech.', 'Offer "cows and goats and hens" beside "cows, goats and hens" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Commas, then and before the last.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T9_PUNCTUATION_THE_COMM.COMMA_LIST.M2_LC_FULL_STOP', 'ENGL.G2.WRITIN.T9_PUNCTUATION_THE_COMM.COMMA_LIST', 'Uses full stops between items.', '{"question":"Punctuate: I see a cow a goat and a hen.","wrong_answer":"I see a cow. a goat. and a hen.","correct_answer":"I see a cow, a goat and a hen."}'::jsonb, 'Comma and full stop are mixed.', 'Offer "I see a cow. a goat. and a hen." beside "I see a cow, a goat and a hen." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A comma has a tail.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T9_PUNCTUATION_THE_COMM.COMMA_LIST.M2_LC_AFTER_AND', 'ENGL.G2.WRITIN.T9_PUNCTUATION_THE_COMM.COMMA_LIST', 'Puts a comma after and.', '{"question":"Punctuate: maize beans and peas","wrong_answer":"maize, beans and, peas","correct_answer":"maize, beans and peas"}'::jsonb, 'A comma is put at every join.', 'Offer "maize, beans and, peas" beside "maize, beans and peas" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'No comma right after and.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T10_PRONUNCIATION_AND_VO.EAR_ER_DR_OI_IE.M2_OI_O', 'ENGL.G2.LISTEN.T10_PRONUNCIATION_AND_VO.EAR_ER_DR_OI_IE', 'Hears oi as o.', '{"question":"The teacher says \"coin\". Coin or cone?","wrong_answer":"cone","correct_answer":"coin"}'::jsonb, 'The glide of oi is not heard.', 'Offer "cone" beside "coin" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Oi slides: o-ee, coin, boy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T10_PRONUNCIATION_AND_VO.EAR_ER_DR_OI_IE.M2_DR_J', 'ENGL.G2.LISTEN.T10_PRONUNCIATION_AND_VO.EAR_ER_DR_OI_IE', 'Hears dr as j.', '{"question":"The teacher says \"drum\". Which sound does it start with: dr or j?","wrong_answer":"j","correct_answer":"dr"}'::jsonb, 'Dr does sound close to j, and the child takes it for j.', 'Offer "j" beside "dr" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'It starts with d, then r: dr-um.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T10_PRONUNCIATION_AND_VO.EAR_ER_DR_OI_IE.M2_ER_E', 'ENGL.G2.LISTEN.T10_PRONUNCIATION_AND_VO.EAR_ER_DR_OI_IE', 'Hears er as the short e.', '{"question":"The teacher says \"turn\". Turn or ten?","wrong_answer":"ten","correct_answer":"turn"}'::jsonb, 'The /ɜː/ sound is missing at home.', 'Offer "ten" beside "turn" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Turn has a long er: lips relaxed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T10_PRONUNCIATION_AND_VO.EAR_ER_DR_OI_IE.M2_EAR_AIR', 'ENGL.G2.LISTEN.T10_PRONUNCIATION_AND_VO.EAR_ER_DR_OI_IE', 'Hears ear as air.', '{"question":"The teacher says \"hear\". Hear or hair?","wrong_answer":"hair","correct_answer":"hear"}'::jsonb, 'The two glides are close.', 'Offer "hair" beside "hear" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ear starts with ee: hear. Air starts with e: hair.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T10_COMPREHENSION.MENTAL_PICTURE.M2_MP_ONE_DETAIL', 'ENGL.G2.READIN.T10_COMPREHENSION.MENTAL_PICTURE', 'Matches only one describing word.', '{"question":"Text: a small brown dog with a long tail. Which picture?","wrong_answer":"a big brown dog","correct_answer":"a small brown dog with a long tail"}'::jsonb, 'One detail is held in mind.', 'Offer "a big brown dog" beside "a small brown dog with a long tail" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check every word: small, brown, long tail.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T10_COMPREHENSION.MENTAL_PICTURE.M2_MP_OWN', 'ENGL.G2.READIN.T10_COMPREHENSION.MENTAL_PICTURE', 'Pictures his or her own home and rejects the text''s picture.', '{"question":"Text: The house had a red roof. Which picture?","wrong_answer":"the house with an iron sheet roof like mine","correct_answer":"the house with a red roof"}'::jsonb, 'Own home is pictured.', 'Offer "the house with an iron sheet roof like mine" beside "the house with a red roof" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Only what the words say.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T10_COMPREHENSION.MENTAL_PICTURE.M2_MP_WHO', 'ENGL.G2.READIN.T10_COMPREHENSION.MENTAL_PICTURE', 'Pictures the wrong one doing the action.', '{"question":"Text: The cat chased the big rat. Which picture?","wrong_answer":"a rat chasing a cat","correct_answer":"a cat chasing a rat"}'::jsonb, 'The order of who did what is lost.', 'Offer "a rat chasing a cat" beside "a cat chasing a rat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Who is chasing?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T10_COMPREHENSION.MENTAL_PICTURE.M2_MP_NUMBER', 'ENGL.G2.READIN.T10_COMPREHENSION.MENTAL_PICTURE', 'Pictures the wrong number of things.', '{"question":"Text: Three birds sat on the wall. Which picture?","wrong_answer":"one bird on a wall","correct_answer":"three birds on a wall"}'::jsonb, 'The number word is skipped.', 'Offer "one bird on a wall" beside "three birds on a wall" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'How many? Three.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T10_PREPOSITIONS.PREPOSITIONS.M2_PP_ABOVE_ON', 'ENGL.G2.LANGUA.T10_PREPOSITIONS.PREPOSITIONS', 'Uses above for on (touching).', '{"question":"The cup is ... the table.","wrong_answer":"above","correct_answer":"on"}'::jsonb, 'Both mean higher.', 'Offer "above" beside "on" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'On touches; above does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T10_PREPOSITIONS.PREPOSITIONS.M2_PP_BELOW_BEHIND', 'ENGL.G2.LANGUA.T10_PREPOSITIONS.PREPOSITIONS', 'Uses below for behind.', '{"question":"The boy hid ... the door.","wrong_answer":"below","correct_answer":"behind"}'::jsonb, 'Position words are not yet secure.', 'Offer "below" beside "behind" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Behind: at the back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T10_PREPOSITIONS.PREPOSITIONS.M2_PP_ACROSS_ALONG', 'ENGL.G2.LANGUA.T10_PREPOSITIONS.PREPOSITIONS', 'Uses across for along.', '{"question":"We walked ... the river bank for an hour.","wrong_answer":"across","correct_answer":"along"}'::jsonb, 'Both describe walking near something.', 'Offer "across" beside "along" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Across: from one side to the other. Along: beside it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T10_PREPOSITIONS.PREPOSITIONS.M2_PP_TO_AT', 'ENGL.G2.LANGUA.T10_PREPOSITIONS.PREPOSITIONS', 'Uses at for movement to a place.', '{"question":"We are going ... the market.","wrong_answer":"at","correct_answer":"to"}'::jsonb, 'Kiswahili kwenda sokoni has no separate to.', 'Offer "at" beside "to" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Moving: to. Already there: at.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T10_PUNCTUATION_THE_EXCL.EXCLAMATION_MARK.M2_XM_EVERY', 'ENGL.G2.WRITIN.T10_PUNCTUATION_THE_EXCL.EXCLAMATION_MARK', 'Uses exclamation marks for ordinary sentences.', '{"question":"Which mark: We walked to school","wrong_answer":"!","correct_answer":"."}'::jsonb, 'The mark looks exciting.', 'Offer "!" beside "." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Only strong feelings or warnings.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T10_PUNCTUATION_THE_EXCL.EXCLAMATION_MARK.M2_XM_NONE', 'ENGL.G2.WRITIN.T10_PUNCTUATION_THE_EXCL.EXCLAMATION_MARK', 'Leaves out the exclamation mark on a warning.', '{"question":"Which mark: Look out","wrong_answer":".","correct_answer":"!"}'::jsonb, 'Full stops are used everywhere.', 'Offer "." beside "!" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A warning gets !', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T10_PUNCTUATION_THE_EXCL.EXCLAMATION_MARK.M2_XM_MIDDLE', 'ENGL.G2.WRITIN.T10_PUNCTUATION_THE_EXCL.EXCLAMATION_MARK', 'Puts the mark in the middle of the sentence.', '{"question":"Correct: Stop! the car is coming.","wrong_answer":"Stop! the car is coming.","correct_answer":"Stop! The car is coming."}'::jsonb, 'The child does not see that ! ends a sentence.', 'Offer "Stop! the car is coming." beside "Stop! The car is coming." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After ! a new sentence starts with a capital.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T10_PUNCTUATION_THE_EXCL.EXCLAMATION_MARK.M2_XM_QUESTION', 'ENGL.G2.WRITIN.T10_PUNCTUATION_THE_EXCL.EXCLAMATION_MARK', 'Uses ! for a question.', '{"question":"Which mark: Where is the dog","wrong_answer":"!","correct_answer":"?"}'::jsonb, 'Both marks are new and mixed.', 'Offer "!" beside "?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Asking: question mark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T11_PRONUNCIATION_AND_VO.FR_OW_OR_SCHWA.M2_OW_O', 'ENGL.G2.LISTEN.T11_PRONUNCIATION_AND_VO.FR_OW_OR_SCHWA', 'Hears ow (cow) as o.', '{"question":"The teacher says \"town\". Town or tone?","wrong_answer":"tone","correct_answer":"town"}'::jsonb, 'The glide of ow is not heard.', 'Offer "tone" beside "town" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ow slides: a-oo, town, cow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T11_PRONUNCIATION_AND_VO.FR_OW_OR_SCHWA.M2_OR_SHORT_O', 'ENGL.G2.LISTEN.T11_PRONUNCIATION_AND_VO.FR_OW_OR_SCHWA', 'Hears or (forest, warm) as short o.', '{"question":"The teacher says \"port\". Port or pot?","wrong_answer":"pot","correct_answer":"port"}'::jsonb, 'One o sound in the home language.', 'Offer "pot" beside "port" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Or is long: port.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T11_PRONUNCIATION_AND_VO.FR_OW_OR_SCHWA.M2_FR_FL', 'ENGL.G2.LISTEN.T11_PRONUNCIATION_AND_VO.FR_OW_OR_SCHWA', 'Hears fr as fl.', '{"question":"The teacher says \"free\". Free or flee?","wrong_answer":"flee","correct_answer":"free"}'::jsonb, 'L and r merged.', 'Offer "flee" beside "free" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Curl the tongue: free.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T11_PRONUNCIATION_AND_VO.FR_OW_OR_SCHWA.M2_ER_END_FULL', 'ENGL.G2.LISTEN.T11_PRONUNCIATION_AND_VO.FR_OW_OR_SCHWA', 'Expects the end of water or flower to sound like its letters.', '{"question":"Which part of \"water\" is weak?","wrong_answer":"wa","correct_answer":"ter (a quick uh)"}'::jsonb, 'Reading by letter.', 'Offer "wa" beside "ter (a quick uh)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The end of water and flower is a quick uh.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T11_FLUENCY.PHRASE_READING.M2_PH_WORD_BY_WORD', 'ENGL.G2.READIN.T11_FLUENCY.PHRASE_READING', 'Reads one word at a time with a stop after each.', '{"question":"Read: In the morning we walked to the river.","wrong_answer":"In. The. Morning. We. Walked.","correct_answer":"In the morning / we walked / to the river."}'::jsonb, 'Each word is decoded alone.', 'Offer "In. The. Morning. We. Walked." beside "In the morning / we walked / to the river." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Scoop the words together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T11_FLUENCY.PHRASE_READING.M2_PH_WRONG_SCOOP', 'ENGL.G2.READIN.T11_FLUENCY.PHRASE_READING', 'Groups words in places that break the meaning.', '{"question":"Read: The big dog / ran away.","wrong_answer":"The big / dog ran / away.","correct_answer":"The big dog / ran away."}'::jsonb, 'The child groups by number of words, not meaning.', 'Offer "The big / dog ran / away." beside "The big dog / ran away." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep the who together, then the what.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T11_FLUENCY.PHRASE_READING.M2_PH_TOO_FAST', 'ENGL.G2.READIN.T11_FLUENCY.PHRASE_READING', 'Rushes and runs all the words together.', '{"question":"Read the sentence smoothly.","wrong_answer":"all words run together, no pauses","correct_answer":"smooth, with short pauses between phrases"}'::jsonb, 'The child thinks fast means good.', 'Offer "all words run together, no pauses" beside "smooth, with short pauses between phrases" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Smooth, not a race.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.READIN.T11_FLUENCY.PHRASE_READING.M2_PH_FINGER_EVERY', 'ENGL.G2.READIN.T11_FLUENCY.PHRASE_READING', 'Taps every word with the finger, which keeps the reading slow.', '{"question":"Read the sentence in scoops.","wrong_answer":"taps and stops at each word","correct_answer":"slides the finger under the phrase"}'::jsonb, 'The pointing habit of Grade 1 is kept.', 'Offer "taps and stops at each word" beside "slides the finger under the phrase" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Slide your finger under the whole scoop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T11_REGULAR_COMPARATIVE_.COMPARE_ER_EST.M2_CM_MORE_ER', 'ENGL.G2.LANGUA.T11_REGULAR_COMPARATIVE_.COMPARE_ER_EST', 'Uses more with -er.', '{"question":"The river is ... than the pond.","wrong_answer":"more cleaner","correct_answer":"cleaner"}'::jsonb, 'Two ways of comparing are mixed.', 'Offer "more cleaner" beside "cleaner" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Cleaner already means more clean.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T11_REGULAR_COMPARATIVE_.COMPARE_ER_EST.M2_CM_ER_FOR_EST', 'ENGL.G2.LANGUA.T11_REGULAR_COMPARATIVE_.COMPARE_ER_EST', 'Uses -er for the whole group.', '{"question":"This is the ... tree in the forest. (tall)","wrong_answer":"taller","correct_answer":"tallest"}'::jsonb, 'The forms are not linked to two and many.', 'Offer "taller" beside "tallest" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The whole group: the -est.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T11_REGULAR_COMPARATIVE_.COMPARE_ER_EST.M2_CM_BIGER', 'ENGL.G2.LANGUA.T11_REGULAR_COMPARATIVE_.COMPARE_ER_EST', 'Does not double the last letter.', '{"question":"A cow is ... than a goat. (big)","wrong_answer":"biger","correct_answer":"bigger"}'::jsonb, 'The spelling rule is not known.', 'Offer "biger" beside "bigger" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Big, bigger: double g.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T11_REGULAR_COMPARATIVE_.COMPARE_ER_EST.M2_CM_NO_THAN', 'ENGL.G2.LANGUA.T11_REGULAR_COMPARATIVE_.COMPARE_ER_EST', 'Leaves out than.', '{"question":"Ali is taller ... Juma.","wrong_answer":"(nothing): Ali is taller Juma","correct_answer":"than"}'::jsonb, 'Kiswahili kuliko is left out in translation.', 'Offer "(nothing): Ali is taller Juma" beside "than" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Taller than.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T11_GUIDED_WRITING.WRITE_SENTENCES.M2_WS_NO_VERB', 'ENGL.G2.WRITIN.T11_GUIDED_WRITING.WRITE_SENTENCES', 'Writes words with no doing word.', '{"question":"Write a sentence about the environment.","wrong_answer":"Clean river.","correct_answer":"We keep the river clean."}'::jsonb, 'The child writes a label, not a sentence.', 'Offer "Clean river." beside "We keep the river clean." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Who does what?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T11_GUIDED_WRITING.WRITE_SENTENCES.M2_WS_NO_CAPITAL', 'ENGL.G2.WRITIN.T11_GUIDED_WRITING.WRITE_SENTENCES', 'Starts with a small letter.', '{"question":"Write: we plant trees.","wrong_answer":"we plant trees.","correct_answer":"We plant trees."}'::jsonb, 'The capital is forgotten.', 'Offer "we plant trees." beside "We plant trees." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start with a capital.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T11_GUIDED_WRITING.WRITE_SENTENCES.M2_WS_NO_STOP', 'ENGL.G2.WRITIN.T11_GUIDED_WRITING.WRITE_SENTENCES', 'Leaves out the full stop.', '{"question":"Write: I pick litter","wrong_answer":"I pick litter","correct_answer":"I pick litter."}'::jsonb, 'The end of the line is taken as the end.', 'Offer "I pick litter" beside "I pick litter." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'End with a full stop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T11_GUIDED_WRITING.WRITE_SENTENCES.M2_WS_RUN_ON', 'ENGL.G2.WRITIN.T11_GUIDED_WRITING.WRITE_SENTENCES', 'Runs two sentences together.', '{"question":"Write two sentences about trees.","wrong_answer":"Trees give shade we plant them","correct_answer":"Trees give shade. We plant them."}'::jsonb, 'Speech has no full stops.', 'Offer "Trees give shade we plant them" beside "Trees give shade. We plant them." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read it aloud: stop where your voice stops.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T12_PRONUNCIATION_AND_VO.GR_PR_OI_OO_U.M2_OO_SHORT_LONG', 'ENGL.G2.LISTEN.T12_PRONUNCIATION_AND_VO.GR_PR_OI_OO_U', 'Hears the long oo (pool) and short oo (pull) as the same.', '{"question":"The teacher says \"pool\". Pool or pull?","wrong_answer":"pull","correct_answer":"pool"}'::jsonb, 'One u sound in the home language.', 'Offer "pull" beside "pool" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Pool is long; pull is short.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T12_PRONUNCIATION_AND_VO.GR_PR_OI_OO_U.M2_GR_KR', 'ENGL.G2.LISTEN.T12_PRONUNCIATION_AND_VO.GR_PR_OI_OO_U', 'Hears gr as cr.', '{"question":"The teacher says \"grow\". Grow or crow?","wrong_answer":"crow","correct_answer":"grow"}'::jsonb, 'G and k are swapped.', 'Offer "crow" beside "grow" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'G buzzes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T12_PRONUNCIATION_AND_VO.GR_PR_OI_OO_U.M2_PR_PL', 'ENGL.G2.LISTEN.T12_PRONUNCIATION_AND_VO.GR_PR_OI_OO_U', 'Hears pr as pl.', '{"question":"The teacher says \"pray\". Pray or play?","wrong_answer":"play","correct_answer":"pray"}'::jsonb, 'L and r merged.', 'Offer "play" beside "pray" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Curl the tongue: pray.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T12_PRONUNCIATION_AND_VO.GR_PR_OI_OO_U.M2_OY_IE', 'ENGL.G2.LISTEN.T12_PRONUNCIATION_AND_VO.GR_PR_OI_OO_U', 'Hears oi (toy) as the long i (tie).', '{"question":"The teacher says \"toy\". Toy or tie?","wrong_answer":"tie","correct_answer":"toy"}'::jsonb, 'The two glides both end in ee.', 'Offer "tie" beside "toy" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Toy starts with o; tie starts with a.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T12_POSSESSIVE_PRONOUNS.POSSESSIVE_PRONOUNS.M2_PO_HIS_HERS', 'ENGL.G2.LANGUA.T12_POSSESSIVE_PRONOUNS.POSSESSIVE_PRONOUNS', 'Uses his for a girl or hers for a boy.', '{"question":"That phone belongs to Mary. It is ...","wrong_answer":"his","correct_answer":"hers"}'::jsonb, 'Kiswahili yake serves both.', 'Offer "his" beside "hers" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A girl: hers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T12_POSSESSIVE_PRONOUNS.POSSESSIVE_PRONOUNS.M2_PO_MINE_NOUN', 'ENGL.G2.LANGUA.T12_POSSESSIVE_PRONOUNS.POSSESSIVE_PRONOUNS', 'Puts mine before a noun.', '{"question":"This is ... radio.","wrong_answer":"mine","correct_answer":"my"}'::jsonb, 'Mine and my are mixed.', 'Offer "mine" beside "my" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'My radio; the radio is mine.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T12_POSSESSIVE_PRONOUNS.POSSESSIVE_PRONOUNS.M2_PO_APOSTROPHE', 'ENGL.G2.LANGUA.T12_POSSESSIVE_PRONOUNS.POSSESSIVE_PRONOUNS', 'Writes an apostrophe in yours or ours.', '{"question":"Is this book ...?","wrong_answer":"your''s","correct_answer":"yours"}'::jsonb, 'The apostrophe of Tom''s is copied.', 'Offer "your''s" beside "yours" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'No apostrophe in yours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T12_POSSESSIVE_PRONOUNS.POSSESSIVE_PRONOUNS.M2_PO_US', 'ENGL.G2.LANGUA.T12_POSSESSIVE_PRONOUNS.POSSESSIVE_PRONOUNS', 'Uses us for ours.', '{"question":"This classroom belongs to us. It is ...","wrong_answer":"us","correct_answer":"ours"}'::jsonb, 'Word for word: ni yetu, it is us.', 'Offer "us" beside "ours" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Belongs to us: ours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T12_GUIDED_WRITING.PICTURE_NAMES.M2_PN_HOME_WORD', 'ENGL.G2.WRITIN.T12_GUIDED_WRITING.PICTURE_NAMES', 'Writes the Kiswahili name.', '{"question":"Write the name: (picture of a radio)","wrong_answer":"redio","correct_answer":"radio"}'::jsonb, 'The Kiswahili word redio is close.', 'Offer "redio" beside "radio" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'In English: radio.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T12_GUIDED_WRITING.PICTURE_NAMES.M2_PN_NEAR', 'ENGL.G2.WRITIN.T12_GUIDED_WRITING.PICTURE_NAMES', 'Names something near the object.', '{"question":"Write the name: (picture of a phone on a table)","wrong_answer":"table","correct_answer":"phone"}'::jsonb, 'The bigger thing is named.', 'Offer "table" beside "phone" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Point at the object first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T12_GUIDED_WRITING.PICTURE_NAMES.M2_PN_SOUND', 'ENGL.G2.WRITIN.T12_GUIDED_WRITING.PICTURE_NAMES', 'Spells the name as it sounds.', '{"question":"Write the name: (picture of a computer)","wrong_answer":"kompyuta","correct_answer":"computer"}'::jsonb, 'Spelling by sound, Kiswahili style.', 'Offer "kompyuta" beside "computer" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look, cover, write, check.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T12_GUIDED_WRITING.PICTURE_NAMES.M2_PN_PLURAL', 'ENGL.G2.WRITIN.T12_GUIDED_WRITING.PICTURE_NAMES', 'Writes a plural for one object.', '{"question":"Write the name: (one television)","wrong_answer":"televisions","correct_answer":"television"}'::jsonb, 'The -s is added from habit.', 'Offer "televisions" beside "television" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One thing: no -s.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T12_GUIDED_WRITING.PICTURE_SENTENCES.M2_PS_LABEL', 'ENGL.G2.WRITIN.T12_GUIDED_WRITING.PICTURE_SENTENCES', 'Writes only the name, not a sentence.', '{"question":"Write a sentence about the picture of a boy using a computer.","wrong_answer":"computer","correct_answer":"The boy is using a computer."}'::jsonb, 'Naming pictures is what the child has done before.', 'Offer "computer" beside "The boy is using a computer." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Who is doing what?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T12_GUIDED_WRITING.PICTURE_SENTENCES.M2_PS_NOT_IN_PICTURE', 'ENGL.G2.WRITIN.T12_GUIDED_WRITING.PICTURE_SENTENCES', 'Writes about something not in the picture.', '{"question":"Picture: a girl listening to the radio.","wrong_answer":"The girl is cooking.","correct_answer":"The girl is listening to the radio."}'::jsonb, 'The child writes what he or she imagines.', 'Offer "The girl is cooking." beside "The girl is listening to the radio." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Write only what you can see.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T12_GUIDED_WRITING.PICTURE_SENTENCES.M2_PS_NO_ING', 'ENGL.G2.WRITIN.T12_GUIDED_WRITING.PICTURE_SENTENCES', 'Leaves out is or are in an -ing sentence.', '{"question":"Picture: children watching TV.","wrong_answer":"The children watching TV.","correct_answer":"The children are watching TV."}'::jsonb, 'The small word is not heard.', 'Offer "The children watching TV." beside "The children are watching TV." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Is or are before -ing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T12_GUIDED_WRITING.PICTURE_SENTENCES.M2_PS_THERE_IS', 'ENGL.G2.WRITIN.T12_GUIDED_WRITING.PICTURE_SENTENCES', 'Writes "There is" for everything.', '{"question":"Picture: a man fixing a phone.","wrong_answer":"There is a man.","correct_answer":"A man is fixing a phone."}'::jsonb, 'One safe pattern is used.', 'Offer "There is a man." beside "A man is fixing a phone." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say what he is doing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T13_BY_THE_END_OF_THE_SU.TR_SM_CH_OW_U.M2_TR_CH', 'ENGL.G2.LISTEN.T13_BY_THE_END_OF_THE_SU.TR_SM_CH_OW_U', 'Hears tr as ch.', '{"question":"The teacher says \"train\". Train or chain?","wrong_answer":"chain","correct_answer":"train"}'::jsonb, 'Tr does sound close to ch.', 'Offer "chain" beside "train" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'It starts with t, then r: t-rain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T13_BY_THE_END_OF_THE_SU.TR_SM_CH_OW_U.M2_SM_SN', 'ENGL.G2.LISTEN.T13_BY_THE_END_OF_THE_SU.TR_SM_CH_OW_U', 'Hears sm as sn.', '{"question":"The teacher says \"smile\". Smile or snail?","wrong_answer":"snail","correct_answer":"smile"}'::jsonb, 'Two nose sounds after s.', 'Offer "snail" beside "smile" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Lips close for sm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T13_BY_THE_END_OF_THE_SU.TR_SM_CH_OW_U.M2_U_YOU', 'ENGL.G2.LISTEN.T13_BY_THE_END_OF_THE_SU.TR_SM_CH_OW_U', 'Misses the y sound in the you vowel.', '{"question":"Which word has the sound in \"you\": cube, cub, cool?","wrong_answer":"cool","correct_answer":"cube"}'::jsonb, 'The y before oo is not heard.', 'Offer "cool" beside "cube" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Cube says k-you-b.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T13_BY_THE_END_OF_THE_SU.TR_SM_CH_OW_U.M2_OU_OA', 'ENGL.G2.LISTEN.T13_BY_THE_END_OF_THE_SU.TR_SM_CH_OW_U', 'Hears ow (how) as long o (hoe).', '{"question":"The teacher says \"crowd\". Crowd or crowed?","wrong_answer":"crowed","correct_answer":"crowd"}'::jsonb, 'Ow can say two sounds and the wrong one is chosen.', 'Offer "crowed" beside "crowd" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Crowd: a-oo, like cow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T13_WH_QUESTIONS.WH_QUESTIONS.M2_WH_WHERE_WHEN', 'ENGL.G2.LANGUA.T13_WH_QUESTIONS.WH_QUESTIONS', 'Swaps where and when.', '{"question":"... is the dance? On Friday.","wrong_answer":"Where","correct_answer":"When"}'::jsonb, 'The two words look and sound alike.', 'Offer "Where" beside "When" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'When: time. Where: place.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T13_WH_QUESTIONS.WH_QUESTIONS.M2_WH_WHO_WHAT', 'ENGL.G2.LANGUA.T13_WH_QUESTIONS.WH_QUESTIONS', 'Uses who for a thing.', '{"question":"... is in the box? A drum.","wrong_answer":"Who","correct_answer":"What"}'::jsonb, 'Who is used for any question.', 'Offer "Who" beside "What" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Who: a person. What: a thing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T13_WH_QUESTIONS.WH_QUESTIONS.M2_WH_ORDER', 'ENGL.G2.LANGUA.T13_WH_QUESTIONS.WH_QUESTIONS', 'Keeps the statement order.', '{"question":"Ask where Juma is going.","wrong_answer":"Where Juma is going?","correct_answer":"Where is Juma going?"}'::jsonb, 'Questions at home keep the statement order.', 'Offer "Where Juma is going?" beside "Where is Juma going?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Swap: is Juma.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T13_WH_QUESTIONS.WH_QUESTIONS.M2_WH_NO_MARK', 'ENGL.G2.LANGUA.T13_WH_QUESTIONS.WH_QUESTIONS', 'Ends a question with a full stop.', '{"question":"Write: Who beat the drum","wrong_answer":"Who beat the drum.","correct_answer":"Who beat the drum?"}'::jsonb, 'Every sentence ends with a full stop.', 'Offer "Who beat the drum." beside "Who beat the drum?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A question mark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T13_GUIDED_WRITING.WORD_ORDER.M2_WO_AS_GIVEN', 'ENGL.G2.WRITIN.T13_GUIDED_WRITING.WORD_ORDER', 'Copies the words in the order given.', '{"question":"Order: drum / beat / Juma / the","wrong_answer":"drum beat Juma the","correct_answer":"Juma beat the drum."}'::jsonb, 'The task is seen as copying.', 'Offer "drum beat Juma the" beside "Juma beat the drum." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Who did it? Start there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T13_GUIDED_WRITING.WORD_ORDER.M2_WO_ADJ_AFTER', 'ENGL.G2.WRITIN.T13_GUIDED_WRITING.WORD_ORDER', 'Puts the describing word after the noun.', '{"question":"Order: a / dress / red / wore / she","wrong_answer":"She wore a dress red.","correct_answer":"She wore a red dress."}'::jsonb, 'Kiswahili puts the describing word after the noun (gauni jekundu).', 'Offer "She wore a dress red." beside "She wore a red dress." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'In English the describing word comes first: red dress.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T13_GUIDED_WRITING.WORD_ORDER.M2_WO_VERB_FIRST', 'ENGL.G2.WRITIN.T13_GUIDED_WRITING.WORD_ORDER', 'Puts the verb first.', '{"question":"Order: danced / the / girls","wrong_answer":"Danced the girls.","correct_answer":"The girls danced."}'::jsonb, 'The action is the most important word.', 'Offer "Danced the girls." beside "The girls danced." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Who first, then what they did.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T13_GUIDED_WRITING.WORD_ORDER.M2_WO_CAPITAL', 'ENGL.G2.WRITIN.T13_GUIDED_WRITING.WORD_ORDER', 'Ignores the capital-letter clue.', '{"question":"Order: market / We / to / went / the","wrong_answer":"went We to the market","correct_answer":"We went to the market."}'::jsonb, 'The capital letter is not seen as a clue.', 'Offer "went We to the market" beside "We went to the market." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The word with the capital goes first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T14_PRONUNCIATION_AND_VO.K_SN_SP_U.M2_C_K_DIFFERENT', 'ENGL.G2.LISTEN.T14_PRONUNCIATION_AND_VO.K_SN_SP_U', 'Thinks c and k at the start make different sounds.', '{"question":"Do \"cook\" and \"kitchen\" start with the same sound?","wrong_answer":"no","correct_answer":"yes"}'::jsonb, 'Different letters are expected to mean different sounds.', 'Offer "no" beside "yes" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'C, k and ck can all say k.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T14_PRONUNCIATION_AND_VO.K_SN_SP_U.M2_SN_SM', 'ENGL.G2.LISTEN.T14_PRONUNCIATION_AND_VO.K_SN_SP_U', 'Hears sn as sm.', '{"question":"The teacher says \"snack\". Snack or smack?","wrong_answer":"smack","correct_answer":"snack"}'::jsonb, 'Two nose sounds after s.', 'Offer "smack" beside "snack" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Lips open for sn.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T14_PRONUNCIATION_AND_VO.K_SN_SP_U.M2_SP_S', 'ENGL.G2.LISTEN.T14_PRONUNCIATION_AND_VO.K_SN_SP_U', 'Does not hear the p in sp.', '{"question":"The teacher says \"spot\". Spot or sot?","wrong_answer":"sot","correct_answer":"spot"}'::jsonb, 'The second consonant is lost.', 'Offer "sot" beside "spot" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'S-p-ot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T14_PRONUNCIATION_AND_VO.K_SN_SP_U.M2_U_A', 'ENGL.G2.LISTEN.T14_PRONUNCIATION_AND_VO.K_SN_SP_U', 'Hears u (cup) as a (cap).', '{"question":"The teacher says \"cup\". Cup or cap?","wrong_answer":"cap","correct_answer":"cup"}'::jsonb, 'Kenyan English uses one a sound for both.', 'Offer "cap" beside "cup" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Cup: short uh with the mouth half open.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T14_ADVERBS_OF_TIME.ADVERBS_TIME.M2_AT_TOMORROW_PAST', 'ENGL.G2.LANGUA.T14_ADVERBS_OF_TIME.ADVERBS_TIME', 'Uses tomorrow with a past verb.', '{"question":"... I helped my father.","wrong_answer":"Tomorrow","correct_answer":"Yesterday"}'::jsonb, 'Yesterday and tomorrow are mixed (Kiswahili jana and kesho are learnt together).', 'Offer "Tomorrow" beside "Yesterday" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Yesterday: past. Tomorrow: future.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T14_ADVERBS_OF_TIME.ADVERBS_TIME.M2_AT_SOON_NOW', 'ENGL.G2.LANGUA.T14_ADVERBS_OF_TIME.ADVERBS_TIME', 'Thinks soon means now.', '{"question":"The bus will come ... (in a short time)","wrong_answer":"now","correct_answer":"soon"}'::jsonb, 'Soon and now both mean not long.', 'Offer "now" beside "soon" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Now: this moment. Soon: in a short time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T14_ADVERBS_OF_TIME.ADVERBS_TIME.M2_AT_EARLY_LATE', 'ENGL.G2.LANGUA.T14_ADVERBS_OF_TIME.ADVERBS_TIME', 'Swaps early and late.', '{"question":"School starts at eight. Ali came at nine. He was ...","wrong_answer":"early","correct_answer":"late"}'::jsonb, 'The pair is learnt together.', 'Offer "early" beside "late" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After the time: late.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T14_ADVERBS_OF_TIME.ADVERBS_TIME.M2_AT_TODAY_TENSE', 'ENGL.G2.LANGUA.T14_ADVERBS_OF_TIME.ADVERBS_TIME', 'Uses today with a mismatched tense.', '{"question":"Today I ... (help) my mother now.","wrong_answer":"helped","correct_answer":"am helping"}'::jsonb, 'Today can be past or present, and the child picks one at random.', 'Offer "helped" beside "am helping" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Today and now: am helping.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T14_GUIDED_WRITING.RECOUNT_EVENTS.M2_RC_ORDER', 'ENGL.G2.WRITIN.T14_GUIDED_WRITING.RECOUNT_EVENTS', 'Writes the events out of order.', '{"question":"Write what happened when Tom helped his sick friend.","wrong_answer":"Tom visited. His friend was sick. He gave him water.","correct_answer":"First Tom''s friend fell sick. Next Tom visited him. Then he gave him water."}'::jsonb, 'Events are written as remembered.', 'Offer "Tom visited. His friend was sick. He gave him water." beside "First Tom''s friend fell sick. Next Tom visited him. Then he gave him water." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'First, next, then, last.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T14_GUIDED_WRITING.RECOUNT_EVENTS.M2_RC_PRESENT', 'ENGL.G2.WRITIN.T14_GUIDED_WRITING.RECOUNT_EVENTS', 'Writes in the present.', '{"question":"Write what happened.","wrong_answer":"Tom visits his friend.","correct_answer":"Tom visited his friend."}'::jsonb, 'The present is the first form learnt.', 'Offer "Tom visits his friend." beside "Tom visited his friend." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'It already happened: past.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T14_GUIDED_WRITING.RECOUNT_EVENTS.M2_RC_ONE', 'ENGL.G2.WRITIN.T14_GUIDED_WRITING.RECOUNT_EVENTS', 'Writes one event and stops.', '{"question":"Write three things that happened.","wrong_answer":"Tom visited his friend.","correct_answer":"Tom visited his friend. He gave him water. He read him a story."}'::jsonb, 'The child does not know how much to write.', 'Offer "Tom visited his friend." beside "Tom visited his friend. He gave him water. He read him a story." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Count three sentences.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T14_GUIDED_WRITING.RECOUNT_EVENTS.M2_RC_AND_THEN', 'ENGL.G2.WRITIN.T14_GUIDED_WRITING.RECOUNT_EVENTS', 'Joins everything with and then in one sentence.', '{"question":"Write what happened.","wrong_answer":"Tom went and then he gave and then he read","correct_answer":"Tom went to see his friend. Then he gave him water."}'::jsonb, 'And then joins speech.', 'Offer "Tom went and then he gave and then he read" beside "Tom went to see his friend. Then he gave him water." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Full stops, then a time word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T15_PRONUNCIATION_AND_VO.SCR_SPR_STR_SW_ST.M2_STR_THREE_BEATS', 'ENGL.G2.LISTEN.T15_PRONUNCIATION_AND_VO.SCR_SPR_STR_SW_ST', 'Hears vowels between the consonants of str.', '{"question":"Clap the beats in \"strong\".","wrong_answer":"3 (si-ti-rong)","correct_answer":"1"}'::jsonb, 'A vowel after every consonant.', 'Offer "3 (si-ti-rong)" beside "1" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Str glued: strong, one clap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T15_PRONUNCIATION_AND_VO.SCR_SPR_STR_SW_ST.M2_SCR_STR', 'ENGL.G2.LISTEN.T15_PRONUNCIATION_AND_VO.SCR_SPR_STR_SW_ST', 'Hears scr as str.', '{"question":"The teacher says \"scrub\". Scrub or stub?","wrong_answer":"stub","correct_answer":"scrub"}'::jsonb, 'The middle sound is missed.', 'Offer "stub" beside "scrub" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Scr has k in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T15_PRONUNCIATION_AND_VO.SCR_SPR_STR_SW_ST.M2_SW_TWO_BEATS', 'ENGL.G2.LISTEN.T15_PRONUNCIATION_AND_VO.SCR_SPR_STR_SW_ST', 'Hears a vowel between s and w.', '{"question":"Clap the beats in \"sweep\".","wrong_answer":"2 (su-weep)","correct_answer":"1"}'::jsonb, 'A vowel after s.', 'Offer "2 (su-weep)" beside "1" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'S and w together: sweep.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LISTEN.T15_PRONUNCIATION_AND_VO.SCR_SPR_STR_SW_ST.M2_STR_SPR', 'ENGL.G2.LISTEN.T15_PRONUNCIATION_AND_VO.SCR_SPR_STR_SW_ST', 'Mixes str and spr.', '{"question":"Which word starts with spr: string, spray, sting?","wrong_answer":"string","correct_answer":"spray"}'::jsonb, 'The middle sound is not heard.', 'Offer "string" beside "spray" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen for the middle: p or t?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.COMMANDS.M2_IM_YOU', 'ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.COMMANDS', 'Starts a command with you.', '{"question":"Tell your friend to sit down.","wrong_answer":"You sit down.","correct_answer":"Sit down, please."}'::jsonb, 'The subject is added as in a statement.', 'Offer "You sit down." beside "Sit down, please." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A command starts with the verb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.COMMANDS.M2_IM_ING', 'ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.COMMANDS', 'Uses an -ing verb in a command.', '{"question":"Tell your friend to close the door.","wrong_answer":"Closing the door.","correct_answer":"Close the door, please."}'::jsonb, 'The -ing form is used for what is happening.', 'Offer "Closing the door." beside "Close the door, please." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Plain verb: close.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.COMMANDS.M2_IM_NO_PLEASE', 'ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.COMMANDS', 'Gives a command to an adult with no polite word.', '{"question":"Ask the teacher to open the window.","wrong_answer":"Open the window.","correct_answer":"Please open the window."}'::jsonb, 'Commands are learnt in class drills.', 'Offer "Open the window." beside "Please open the window." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'To adults: please.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.COMMANDS.M2_IM_S', 'ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.COMMANDS', 'Adds -s to the verb of a command.', '{"question":"Tell the class to stand up.","wrong_answer":"Stands up.","correct_answer":"Stand up."}'::jsonb, 'The -s of he stands is carried in.', 'Offer "Stands up." beside "Stand up." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'No -s: stand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.EXCITEMENT_WORDS.M2_EX_SAD_WORD', 'ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.EXCITEMENT_WORDS', 'Uses a sad word for joy.', '{"question":"We won the dance competition! \"...!\"","wrong_answer":"Oh no","correct_answer":"Hurray"}'::jsonb, 'Interjections are learnt as a list.', 'Offer "Oh no" beside "Hurray" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Hurray is for joy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.EXCITEMENT_WORDS.M2_EX_NO_MARK', 'ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.EXCITEMENT_WORDS', 'Leaves out the exclamation mark.', '{"question":"Write: Wow what a big drum","wrong_answer":"Wow what a big drum.","correct_answer":"Wow! What a big drum!"}'::jsonb, 'The interjection is written as part of the sentence.', 'Offer "Wow what a big drum." beside "Wow! What a big drum!" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'An exclamation mark after Wow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.EXCITEMENT_WORDS.M2_EX_HOME_WORD', 'ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.EXCITEMENT_WORDS', 'Uses a home-language exclamation in English.', '{"question":"Write what you say when you see a beautiful dance.","wrong_answer":"Aii! It is nice.","correct_answer":"Wow! It is beautiful."}'::jsonb, 'Everyday Kenyan exclamations are carried in.', 'Offer "Aii! It is nice." beside "Wow! It is beautiful." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'In English: Wow, Hurray.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.EXCITEMENT_WORDS.M2_EX_EVERY', 'ENGL.G2.LANGUA.T15_IMPERATIVES_COMMANDS.EXCITEMENT_WORDS', 'Puts an interjection in every sentence.', '{"question":"Write two sentences about the festival.","wrong_answer":"Wow! We danced. Wow! We ate.","correct_answer":"Wow! We danced all day. Then we ate together."}'::jsonb, 'Interjections feel exciting.', 'Offer "Wow! We danced. Wow! We ate." beside "Wow! We danced all day. Then we ate together." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Only where the feeling is strong.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T15_GUIDED_WRITING.PUNCTUATE_SENTENCES.M2_PU_NAMES', 'ENGL.G2.WRITIN.T15_GUIDED_WRITING.PUNCTUATE_SENTENCES', 'Writes names with small letters.', '{"question":"Correct: mary visited grandma in kisumu.","wrong_answer":"Mary visited grandma in kisumu.","correct_answer":"Mary visited Grandma in Kisumu."}'::jsonb, 'Only the first word gets a capital.', 'Offer "Mary visited grandma in kisumu." beside "Mary visited Grandma in Kisumu." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Names of people and places: capitals.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T15_GUIDED_WRITING.PUNCTUATE_SENTENCES.M2_PU_SMALL_I', 'ENGL.G2.WRITIN.T15_GUIDED_WRITING.PUNCTUATE_SENTENCES', 'Writes i for I.', '{"question":"Correct: Tom and i helped.","wrong_answer":"Tom and i helped.","correct_answer":"Tom and I helped."}'::jsonb, 'I looks like a small word.', 'Offer "Tom and i helped." beside "Tom and I helped." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'I alone is a capital.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T15_GUIDED_WRITING.PUNCTUATE_SENTENCES.M2_PU_QUESTION_STOP', 'ENGL.G2.WRITIN.T15_GUIDED_WRITING.PUNCTUATE_SENTENCES', 'Ends a question with a full stop.', '{"question":"Which mark: Are you feeling better","wrong_answer":".","correct_answer":"?"}'::jsonb, 'Full stops are used for all.', 'Offer "." beside "?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Asking: question mark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G2.WRITIN.T15_GUIDED_WRITING.PUNCTUATE_SENTENCES.M2_PU_AFTER_STOP', 'ENGL.G2.WRITIN.T15_GUIDED_WRITING.PUNCTUATE_SENTENCES', 'Forgets the capital after a full stop.', '{"question":"Correct: We helped. we cared.","wrong_answer":"We helped. we cared.","correct_answer":"We helped. We cared."}'::jsonb, 'Only the first sentence gets a capital.', 'Offer "We helped. we cared." beside "We helped. We cared." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After a full stop: capital.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
